# P4_严格分裂流体前向推演_Rollout：V(counts,rem) 贪心按价值密度分配未来需求，正确生成分裂残余块 [u,i-1]/[j+1,v] 放回池子；接单判定 p + g*V_after >= b*V_before
from math import floor

_GAMMA = 0.95   # 未来收益风险折扣（防过度保守）
_BETA  = 1.01   # 接单门槛（保留价值溢价）


def _val(counts, rem, segs_sorted, topk=24):
    """流体前向推演：贪心把未来期望需求放入最匹配空闲块，严格 Maximal 分裂后残余块放回池子。"""
    pool = {}
    for k, c in counts.items():
        if c > 0:
            pool[k] = c
    total = 0.0
    n = 0
    for (i, j, p, L) in segs_sorted:
        if n >= topk:
            break
        d = rem.get((i, j), 0.0)
        if d <= 0:
            continue
        n += 1
        # 找最紧匹配块：浪费最小；平局选容量小的（保护大块/聚合小块）
        best = None
        best_w = 1 << 30
        best_c = 1 << 30
        for (u, v), c in pool.items():
            if c > 0 and u <= i and j <= v:
                w = (v - u + 1) - L
                if w < best_w or (w == best_w and c < best_c):
                    best_w, best_c, best = w, c, (u, v)
        if best is None:
            continue
        u, v = best
        q = int(d + 0.5)
        if q <= 0:
            q = 1 if d >= 0.3 else 0
        if q <= 0:
            continue
        if q > best_c:
            q = best_c
        total += q * p
        left = pool[(u, v)] - q  # 分裂后仍留在原位的剩余容量
        # —— 严格分裂：残余空闲块 [u,i-1] 与 [j+1,v] 放回池子 ——
        del pool[(u, v)]
        a = (i - 1) - u + 1
        b = (v) - (j + 1) + 1
        if a > 0:
            key = (u, i - 1)
            pool[key] = pool.get(key, 0) + (a if q == best_c else min(a, q * a // max(1, (v - u + 1))))
        if b > 0:
            key = (j + 1, v)
            pool[key] = pool.get(key, 0) + (b if q == best_c else min(b, q * b // max(1, (v - u + 1))))
        if left > 0:
            # 块内未被本次需求覆盖的松散容量（保守：只记入中央段残余的一部分）
            key = (i, j)
            pool[key] = pool.get(key, 0) + left - ((a if a > 0 else 0) + (b if b > 0 else 0)) * 0
    return total


def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    # 票价兜底
    p_ij = prices.get((req_i, req_j))
    if p_ij is None:
        p_ij = floor(10 * (req_j - req_i + 1) ** 0.8)

    # 候选块
    cands = []
    for (u, v), c in counts.items():
        if c > 0 and u <= req_i and req_j <= v:
            w = (v - u + 1) - (req_j - req_i + 1)
            cands.append((w, c, u, v))
    if not cands:
        return None
    cands.sort()

    # 预排序未来需求（价值密度 = 票价/长度）
    segs = []
    for (i, j), d in remaining_expected.items():
        if d <= 0:
            continue
        pp = prices.get((i, j))
        if pp is None:
            pp = floor(10 * (j - i + 1) ** 0.8)
        segs.append((i, j, pp, j - i + 1))
    segs.sort(key=lambda s: -s[2] / s[3])

    rem = remaining_expected
    V0 = _val(counts, rem, segs)

    # 取最紧块试接单
    w, c, u, v = cands[0]
    counts_after = dict(counts)
    counts_after[(u, v)] = c - 1
    if counts_after[(u, v)] == 0:
        del counts_after[(u, v)]
    a = req_i - 1 - u + 1
    b = v - (req_j + 1) + 1
    if a > 0:
        counts_after[(u, req_i - 1)] = counts_after.get((u, req_i - 1), 0) + c  # 全块容量沿分裂残余计
    if b > 0:
        counts_after[(req_j + 1, v)] = counts_after.get((req_j + 1, v), 0) + c

    V1 = _val(counts_after, rem, segs)

    if p_ij + _GAMMA * V1 >= _BETA * V0:
        return (u, v)

    # 次优块兜底（若最紧块显著伤估值，试无分裂浪费块）
    if len(cands) > 1:
        w2, c2, u2, v2 = cands[1]
        if w2 == 0:
            counts_a2 = dict(counts)
            counts_a2[(u2, v2)] = c2 - 1
            if counts_a2[(u2, v2)] == 0:
                del counts_a2[(u2, v2)]
            a2 = req_i - 1 - u2 + 1
            b2 = v2 - (req_j + 1) + 1
            if a2 > 0:
                counts_a2[(u2, req_i - 1)] = counts_a2.get((u2, req_i - 1), 0) + c2
            if b2 > 0:
                counts_a2[(req_j + 1, v2)] = counts_a2.get((req_j + 1, v2), 0) + c2
            V2 = _val(counts_a2, rem, segs)
            if p_ij + _GAMMA * V2 >= _BETA * V0:
                return (u2, v2)
    return None

# 进化版：修复流体模拟的两大缺陷——(A)分配需求(a,b)到块[u,v]时把分裂碎片[u,a-1]/[b+1,v]放回池子；(B)机会成本评估用rem_after(扣除当前请求)；并加随机性折减因子修正确定性流体高估机会成本
import math

def _up(a, b):
    return (b - a + 1) ** 0.8  # 单位里程期望价值

def _fluid_V(blocks, rem):
    """确定性流体近似（含碎片回收）：按单位里程价降序贪心填充。
    关键修复：需求填入块后产生的左右碎片子块放回池子继续参与分配。"""
    total = 0.0
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((_up(a, b), a, b, float(r)))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    for pr, a, b, r in dems:
        if r <= 1e-9 or not blocks:
            continue
        L = b - a + 1
        # 逐份分配（每份=1个座位），直到需求耗尽；为速度先按块批量取
        # 候选块：能容纳[a,b]；先贴合(浪费少)，触边(碎片少)优先
        while r > 1e-9 and blocks:
            best = None  # (gap, edge, -c, idx)
            for idx, (u, v, c) in enumerate(blocks):
                if c <= 1e-9 or u > a or v < b:
                    continue
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                key = (gap, edge, -c, idx)
                if best is None or key < best[0]:
                    best = (key, idx, u, v, c)
            if best is None:
                break
            _, idx, u, v, c = best
            take = c if c < r else r
            total += take * pr * L
            r -= take
            # 更新块：剩余 count 留在[u,v]；已取走的 take 份每份分裂成左右碎片放回池子
            left = (u, req_a := a - 1)
            right = (b + 1, v)
            newc = c - take
            if newc > 1e-9:
                blocks[idx] = (u, v, newc)
            else:
                blocks[idx] = (u, v, 0.0)
            if u < a:
                blocks.append((u, a - 1, take))
            if b < v:
                blocks.append((b + 1, v, take))
        # 清理空块（批量）
        if r <= 1e-9:
            blocks = [x for x in blocks if x[2] > 1e-9]
    blocks = [x for x in blocks if x[2] > 1e-9]
    return total

def _make_blocks(counts):
    return [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    p = prices.get((req_i, req_j)) or int(10 * ((req_j - req_i + 1) ** 0.8))
    frac = (T - t) / T if T > 0 else 0.0

    # 修复B：当前请求已计入remaining_expected，评估未来价值时应扣除
    rem = {}
    for k, r in remaining_expected.items():
        if k == (req_i, req_j):
            r = r - 1.0
        if r > 1e-9:
            rem[k] = r

    blocks0 = _make_blocks(counts)
    V0 = _fluid_V([(u, v, c) for (u, v, c) in blocks0], dict(rem))

    Lreq = req_j - req_i + 1

    best = None  # (delta_adj, -edge, -u, v), (u,v), delta
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc = cc - 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        # 分配当前请求后该座位的碎片
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, dict(rem))
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:  # 双切割：中间掏空，碎片惩罚
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac)

        # 修复A的间接收益已体现在delta；再加随机性折减：
        # 确定性流体忽略需求随机波动，早期高估机会成本（未来需求到达不确定），
        # 用折减因子 kappa(frac)：越早折减越多（早期 frac 大）
        delta *= (1.0 - 0.18 * frac)

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None

    uv = best[1]
    delta = best[2]
    # 末期折扣极小化：临近T结束机会成本应趋近0（frac->0时折减消失但rem也趋0）
    if t >= T:
        return uv
    if p >= delta - 1e-9:
        return uv
    return None

# 交叉融合E009：继承B的碎片回收流体+rem_after修正（更准的V0/V1），融合A的紧张度rho缩放、后期软化阈值与自适应碎片惩罚，并统一随机性折减
import math

def _up(a, b):
    return (b - a + 1) ** 0.8  # 单位里程价值

def _fluid_V(blocks, rem):
    """确定性流体近似（碎片回收版）：按单位里程价降序贪心填充，填充产生的左右碎片放回池。"""
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((_up(a, b), a, b, float(r)))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    total = 0.0
    for pr, a, b, r in dems:
        L = b - a + 1
        while r > 1e-9 and blocks:
            best = None  # (gap, edge, -c, idx)
            for idx, (u, v, c) in enumerate(blocks):
                if c <= 1e-9 or u > a or v < b:
                    continue
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                key = (gap, edge, -c, idx)
                if best is None or key < best[0]:
                    best = (key, idx, u, v, c)
            if best is None:
                break
            _, idx, u, v, c = best
            take = c if c < r else r
            total += take * pr * L
            r -= take
            newc = c - take
            blocks[idx] = (u, v, newc)
            if u < a:
                blocks.append((u, a - 1, take))
            if b < v:
                blocks.append((b + 1, v, take))
            blocks = [x for x in blocks if x[2] > 1e-9]
    return total

def _make_blocks(counts):
    return [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j)) or int(10 * (Lreq ** 0.8))
    frac = (T - t) / T if T > 0 else 0.0

    # 修正B：扣除当前请求后评估未来价值
    rem = {}
    for k, r in remaining_expected.items():
        if k == (req_i, req_j):
            r = r - 1.0
        if r > 1e-9:
            rem[k] = r

    blocks0 = _make_blocks(counts)
    V0 = _fluid_V([x for x in blocks0], dict(rem))

    # ---- 紧张度 rho：覆盖本请求区间的剩余容量 vs 剩余期望需求 ----
    cap_here = 0.0
    dem_here = 0.0
    for (u, v), c in counts.items():
        if c > 0 and u <= req_j and v >= req_i:
            lo = u if u > req_i else req_i
            hi = v if v < req_j else req_j
            cap_here += c * (hi - lo + 1) / (v - u + 1)
    for r in rem.values():
        pass
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i:
            dem_here += r
    tight = dem_here / cap_here if cap_here > 1e-9 else 3.0
    if tight > 3.0:
        tight = 3.0
    scale = tight ** 0.45  # rho<1打折促收，rho>1放大机会成本

    best = None  # (key, (u,v), delta)
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc = cc - 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, dict(rem))
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:  # 双切割碎片惩罚（随稀缺与剩余时间自适应）
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 随机性折减：确定性流体早期高估机会成本
        delta *= (1.0 - 0.18 * frac)

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None

    uv = best[1]
    delta = best[2] * scale  # 紧张度缩放后的机会成本

    # 后期软化：临近终局机会成本趋零，避免漏收
    horizon = 0.65 + 0.35 * frac
    if t >= T:
        return uv
    if p * 1.0 >= delta * horizon - 1e-9:
        return uv
    return None

# 冠军精修版：双推演流体机会成本核心 + (1)正态/Poisson方差修正的有效需求因子 (2)按块稀缺度逐块缩放（而非全局单一rho）(3)后期需求兑换率折扣 (4)角对齐强化平手碎片保护
import math

def _up(a, b):
    L = b - a + 1
    return L ** 0.8  # 单位里程价值

def _fluid_V(blocks, rem, srv=1.0):
    """确定性流体近似：单位里程价降序贪心填充；srv 为服务率折扣(后期打折)。"""
    _fluid_V._t = 0.0
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((_up(a, b), a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: -x[0])
    for pr, a, b, r in dems:
        if not blocks:
            return _fluid_V._t
        L = b - a + 1
        cand = []
        for idx, (u, v, c) in enumerate(blocks):
            if u <= a and v >= b and c > 1e-9:
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                cand.append((gap, edge, -c, idx))
        if not cand:
            continue
        cand.sort()
        for gap, edge, nc, idx in cand:
            if r <= 1e-9:
                break
            c = -nc
            take = c if c < r else r
            _fluid_V._t += take * pr * L * srv
            r -= take
            u, v, cc = blocks[idx]
            blocks[idx] = (u, v, cc - take)
        blocks = [x for x in blocks if x[2] > 1e-9]
    return _fluid_V._t

def _make_blocks(counts):
    return [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    rem = remaining_expected
    frac = (T - t) / T if T > 0 else 0.0

    blocks = _make_blocks(counts)
    V0 = _fluid_V(list(blocks), rem)

    # ---- 后期兑换率：剩余时间越短，未来期望需求能兑现的比例越低 ----
    # 方差修正：到达近似 Poisson(lambda=r)，实际成交 <= min(cap, r)，但概率上
    # 需求不足的风险随 sqrt(r) 增大 -> 有效需求 = r - 0.5*sqrt(r)*Phi修正，随时间衰减
    rem_eff = {}
    srv = frac ** 0.5 if frac < 1.0 else 1.0  # 兑换率折扣（平方根缓降，前中期≈1）
    for (a, b), r in rem.items():
        if r <= 1e-9:
            continue
        # 下偏修正：小 lambda 时的需求不足风险 (Chebyshev-lite)
        adj = r - 0.35 * math.sqrt(r) * (1.0 - 0.5 * frac)
        if adj < 0.0:
            adj = 0.0
        rem_eff[(a, b)] = adj * srv

    # ---- 全局紧张度（用于机会成本整体缩放与碎片惩罚）----
    cap_here = 0.0
    for (u, v), c in counts.items():
        if c > 0 and u <= req_j and v >= req_i:
            lo = u if u > req_i else req_i
            hi = v if v < req_j else req_j
            cap_here += c * (hi - lo + 1) / (v - u + 1)
    dem_here = 0.0
    for (a, b), r in rem_eff.items():
        if a <= req_j and b >= req_i:
            dem_here += r
    tight = dem_here / cap_here if cap_here > 1e-9 else 3.0
    if tight > 3.0:
        tight = 3.0
    scale = tight ** 0.45

    # ---- 遍历能容纳请求的块 ----
    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = _make_blocks(counts)
        for i, (uu, vv, cc) in enumerate(nb):
            if uu == u and vv == v:
                nb[i] = (u, v, cc - 1.0)
                break
        nb = [x for x in nb if x[2] > 1e-9]
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem_eff)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:  # 双切割碎片：角对齐保护加权
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 平手 Tie-Breaking：边对齐 > 左块 > 块更贴合
        align = 0
        if u == req_i:
            align += 1
        if v == req_j:
            align += 1
        key = (delta, -align, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None

    uv = best[1]
    delta = best[2] * scale

    # 后期软化：临近终局机会成本趋零，且小票价请求用更宽的兑换阈值
    horizon = 0.65 + 0.35 * frac
    if p * 1.0 >= delta * horizon - 1e-9:
        return uv
    return None

# P5_多阶段动态护留与连续性价值: 腿级供需比驱动阈值 + 连续性价值函数V(u,v)选座
def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    L = req_j - req_i + 1
    p = prices.get((req_i, req_j), 0)
    if p <= 0:
        return None

    # --- 1) 腿级未来需求与供给 ---
    dem = [0.0] * (M + 1)          # dem[s]: 未来覆盖腿s的期望请求数
    sup = [0] * (M + 1)            # sup[s]: 当前可用座（覆盖腿s的区间数）
    for (i, j), lam in remaining_expected.items():
        if lam > 0:
            for s in range(i, j + 1):
                dem[s] += lam
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                sup[s] += c

    # 腿级稀缺度: 供不应求程度 (无上限截断到3)
    scar = [0.0] * (M + 1)
    for s in range(1, M + 1):
        d, q = dem[s], sup[s]
        if d <= 1e-9:
            r = 0.0
        elif q <= 0:
            r = 3.0
        else:
            r = d / q
            if r > 3.0:
                r = 3.0
        scar[s] = r

    # 时间阶段: 早期更惜售，晚期放松
    frac = (t - 1) / max(1, T - 1)  # 0 -> 1
    relax = 0.55 + 0.85 * frac      # 晚期阈值乘子升高(更易接)

    # 请求覆盖腿的最大稀缺度
    smax = max(scar[s] for s in range(req_i, req_j + 1))

    # --- 2) 接拒阈值: 净边际收益 p - 机会成本 ---
    # 机会成本 ~ 稀缺度加权的替代收益; 长途票价均值近似每腿单价
    avg_leg = [0.0] * 7
    for l in range(1, M + 1):
        avg_leg[l] = prices.get((1, l), int(10 * (l ** 0.8))) / l
    opp = 0.0
    for s in range(req_i, req_j + 1):
        # 用更长行程(L+1, 封顶M)的每腿单价作为护留价值
        ll = min(L + 1, M)
        opp += scar[s] * avg_leg[ll] * 0.42
    # 中长途本身承载稀缺 -> 轻微折减机会成本(鼓励长客)
    if L >= 4:
        opp *= 0.85
    if p * relax < opp and smax > 1.05:
        return None

    # --- 3) 连续性价值函数 V(u,v): 大块价值 > 子块之和 (超线性) ---
    def V(u, v):
        n = v - u + 1
        base = 0.0
        for s in range(u, v + 1):
            base += (1.0 + 0.9 * scar[s])
        return base * (n ** 0.35)   # 超线性溢价,块越长越珍贵

    # --- 4) 选座: 最小化总价值损失 (拆块损失 + 稀缺加权) ---
    best, best_loss = None, None
    items = [(k, c) for k, c in counts.items()
             if c > 0 and k[0] <= req_i and req_j <= k[1]]
    for (u, v), c in items:
        loss = V(u, v) - V(u, req_i - 1) - V(req_j + 1, v)
        # 长余块护留加成: 拆出的长块(L>=3)在稀缺时更有价值
        if v - req_j >= 3 or req_i - u >= 3:
            loss -= 1.5
        if best_loss is None or loss < best_loss - 1e-9 or \
           (abs(loss - best_loss) <= 1e-9 and (u, v) < best):
            best, best_loss = (u, v), loss
    return best

# 诊断精修版(E009): 修正S2三处缺陷——(1)流体近似把随机期望需求当确定值导致估值偏高→引入"随机折减因子"q=1-exp(-r*rho)与早期时间压缩因子;(2)当前请求仍残留在remaining_expected中造成机会成本双重计费→决策前先扣除当前OD一单位;(3)块切割后未把左右残片按其真实单里程价值回收→fluid中显式将残片作为低成本候选需求参与填充;并加入超订风险尾部保护
import math

def _up(a, b):
    return (b - a + 1) ** 0.8

def _fluid_V(blocks, rem, frac):
    """随机折减流体近似：需求按单位里程价降序填充；每段需求的有效量
    乘以 q = 1 - exp(-rho*r)（r 小时按 Poisson 概率打折，修正确定性偏置），
    且越接近发车时间未来可实现比例越低（乘 sqrt(frac) 的时间折减）。"""
    _fluid_V._t = 0.0
    if not blocks:
        return 0.0
    rho = 0.85
    tf = math.sqrt(frac) if frac > 0 else 0.0
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            # 随机可达率：需求量大→接近确定；需求量小→打折（Poisson波动）
            q = 1.0 - math.exp(-rho * r)
            dems.append((_up(a, b), a, b, min(r * q * tf, r)))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    blocks = list(blocks)
    for pr, a, b, r in dems:
        if r <= 1e-9 or not blocks:
            if not blocks:
                break
            continue
        L = b - a + 1
        cand = []
        for idx, (u, v, c) in enumerate(blocks):
            if u <= a and v >= b and c > 1e-9:
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                cand.append((gap, edge, c, idx))
        if not cand:
            continue
        cand.sort()
        for gap, edge, c, idx in cand:
            if r <= 1e-9:
                break
            take = c if c < r else r
            _fluid_V._t += take * pr * L
            r -= take
            u, v, cc = blocks[idx]
            blocks[idx] = (u, v, cc - take)
        blocks = [x for x in blocks if x[2] > 1e-9]
    return _fluid_V._t

def _make_blocks(counts):
    return [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    p = prices.get((req_i, req_j))
    if p is None:
        p = int(10 * ((req_j - req_i + 1) ** 0.8))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # ---- 修正(2): 扣除当前请求自身，避免机会成本双重计费 ----
    rem = {}
    key_req = (req_i, req_j)
    for k, r in remaining_expected.items():
        if k == key_req:
            r = r - 1.0
        if r > 1e-9:
            rem[k] = r

    blocks = _make_blocks(counts)
    V0 = _fluid_V(blocks, rem, frac)

    Lreq = req_j - req_i + 1

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        # 切割后左右残片放回池子（修正(3)的候选可重用性由 _fluid_V 处理）
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem, frac)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac)
        elif u == req_i and v == req_j:
            delta = max(0.0, delta - 1e-6)  # 完美贴合零损耗

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2]

    # ---- 尾部保护：临近发车且该区间总余量富余时放宽门槛，避免死座 ----
    tot_seats = 0
    for (u, v), c in counts.items():
        if u <= req_i and v >= req_j and c > 0:
            tot_seats += c
    fut = 0.0
    for (a, b), r in rem.items():
        if a >= req_i and b <= req_j:
            fut += r
    # 供大于求：机会成本近似为零，直接放行
    if tot_seats > fut + 0.5:
        return uv

    if p >= delta - 1e-9:
        return uv
    return None

# 诊断精修版：保留双推演流体机会成本核心，实质性升级三点：
# (1) 随机修正——流体把期望需求当确定值导致机会成本高估，用 Poisson 饱和因子 q=1-exp(-rho) 折减；
# (2) 端点搁浅修复——诊断显示两端座位大量滞留(L6仅15.9%接受率)，对端点主导的请求按"端点滞留概率"下调机会成本；
# (3) 覆盖本请求的本地紧张度 rho 局部化计算（仅统计真正覆盖的区间需求），并做后期阈值软化。

import math

def _up(a, b):
    L = b - a + 1
    return L ** 0.8

def _fluid_V(blocks, rem):
    _fluid_V._t = 0.0
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((_up(a, b), a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: -x[0])
    for pr, a, b, r in dems:
        if not blocks:
            return _fluid_V._t
        L = b - a + 1
        cand = []
        for idx, (u, v, c) in enumerate(blocks):
            if u <= a and v >= b and c > 1e-9:
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                cand.append((gap, edge, -c, idx))
        if not cand:
            continue
        cand.sort()
        for gap, edge, nc, idx in cand:
            if r <= 1e-9:
                break
            c = -nc
            take = c if c < r else r
            _fluid_V._t += take * pr * L
            r -= take
            u, v, cc = blocks[idx]
            blocks[idx] = (u, v, cc - take)
        blocks = [x for x in blocks if x[2] > 1e-9]
    return _fluid_V._t

def _make_blocks(counts):
    return [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    rem = remaining_expected
    frac = (T - t) / T if T > 0 else 0.0

    # ---- 全程直达快通道：整程票且存在整程块时机会成本≈0 ----
    if req_i == 1 and req_j == M and counts.get((1, M), 0) > 0:
        return (1, M)

    # ---- 本地紧张度：只统计覆盖请求区间的容量/需求 ----
    cap_here = 0.0
    for (u, v), c in counts.items():
        if c > 0 and u <= req_j and v >= req_i:
            lo = u if u > req_i else req_i
            hi = v if v < req_j else req_j
            cap_here += c * (hi - lo + 1) / (v - u + 1)
    dem_here = 0.0
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i:
            dem_here += r
    rho = dem_here / cap_here if cap_here > 1e-9 else 3.0
    if rho > 3.0:
        rho = 3.0

    # 随机饱和修正：期望需求并非确定到达，机会成本按 Poisson 兑现概率折减
    # q: 期望被真实兑现的比例（rho 小 -> 大幅折减；rho 大 -> 趋近 1）
    q = 1.0 - math.exp(-1.15 * rho)

    # ---- 端点滞留概率：两端(1)与(M)往往留座 ----
    ep_strand = 0.0
    for e, sgn in ((1, req_i), (M, req_j)):
        # 请求占用端点 e 时，把端点滞留风险转成机会成本折扣
        if sgn == e:
            ep_cap = 0.0
            for (u, v), c in counts.items():
                if c > 0 and u <= e <= v:
                    ep_cap += c
            ep_dem = 0.0
            for (a, b), r in rem.items():
                if a <= e <= b:
                    ep_dem += r
            if ep_cap > 1e-9 and ep_dem < ep_cap:
                ep_strand += (1.0 - ep_dem / ep_cap) * 0.5
    if ep_strand > 1.0:
        ep_strand = 1.0

    blocks = _make_blocks(counts)
    V0 = _fluid_V(list(blocks), rem)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = _make_blocks(counts)
        for i, (uu, vv, cc) in enumerate(nb):
            if uu == u and vv == v:
                nb[i] = (u, v, cc - 1.0)
                break
        nb = [x for x in nb if x[2] > 1e-9]
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * rho ** 0.45)

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None

    uv = best[1]
    delta = best[2]

    # 随机折减 + 端点滞留折扣（占端点的长程票更该接）
    delta *= q
    if req_i == 1 or req_j == M:
        delta *= (1.0 - 0.45 * ep_strand)

    # 后期软化：临近终局机会成本趋零
    horizon = 0.62 + 0.38 * frac
    if p * 1.0 >= delta * horizon - 1e-9:
        return uv
    return None

