import math

_UPC = {}

def _up(a, b):
    k = b - a + 1
    v = _UPC.get(k)
    if v is None:
        v = k ** 0.8
        _UPC[k] = v
    return v

def _fluid_V(blocks, dems):
    """确定性流体近似（碎片回收版）：dems已按单位里程价降序。"""
    total = 0.0
    for pr, a, b, r in dems:
        L = b - a + 1
        while r > 1e-9 and blocks:
            best = None
            for idx in range(len(blocks)):
                u, v, c = blocks[idx]
                if c <= 1e-9 or u > a or v < b:
                    continue
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                key = (gap, edge, -c, idx)
                if best is None or key < best[0]:
                    best = (key, idx, u, v, c)
            if best is None:
                break
            _, idx, u, v, c = best
            take = c if c < r else r
            total += take * pr * L
            r -= take
            newc = c - take
            blocks[idx] = (u, v, newc)
            if u < a:
                blocks.append((u, a - 1, take))
            if b < v:
                blocks.append((b + 1, v, take))
            blocks = [x for x in blocks if x[2] > 1e-9]
    return total

def _make_dems(rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((_up(a, b), a, b, float(r)))
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    return dems

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
