import math

def _alloc_demand(blocks, a, b, r, pr):
    """把需求量 r 放进能覆盖 [a,b] 的块；正确分裂出左右余段，返回收入。"""
    L = b - a + 1
    total = 0.0
    # 候选：贴合度优先（少浪费长块），同贴合取剩余容量小者
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            waste = (v - u + 1) - L
            cand.append((waste, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        # 精确残留：本块容量 c-take 仍在全段，另派生左右余段各 take 容量
        blocks[idx] = (u, v, c - take)
