    # 未来竞争流强度按剩余时间步归一（早期总强度大但分布长，竞争未必在本座到达前兑现）
    tnorm = steps_left / T if T > 0 else 1.0
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i and _up(a, b) >= up_req - 1e-9 and (a, b) != (req_i, req_j):
            lam += r * (0.45 + 0.55 * tnorm)
    comp = 1.0 - _exp(-lam)

    stoch = (0.60 + 0.40 * fill) * (0.55 + 0.45 * comp) * (1.0 - 0.15 * frac)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc = cc - 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        fragL = fragR = 0
        if u < req_i:
            fragL = req_i - u
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            fragR = v - req_j
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, dict(rem))
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if fragL > 0 and fragR > 0:  # 双切割惩罚
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        edge = 1 if (u == req_i or v == req_j) else 0
        # 碎片整合度：切割后两侧碎片越短越好（易被短单消化）
        fragpen = min(fragL, fragR) if (fragL or fragR) else 0
        key = (delta, -edge, fragpen, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None

    uv = best[1]
    d0 = best[2]

    # 凹折减：流体delta线性叠加高估长程收益，按 sqrt 形态折减（凸收益的实际可兑现性更低）
    if d0 > 0.0:
        d_red = (0.62 * d0 + 0.38 * _sqrt(d0 * max(d0, 1.0)))
    else:
        d_red = 0.0
    delta = d_red * scale * stoch

    horizon = 0.65 + 0.35 * frac
    # 终局清仓：最后若干步且余量明显大于剩余期望时直接收
    if steps_left <= 6:
        remtot = sum(dem_s[req_i:req_j + 1])
        if remtot <= 0.5 * max(1e-9, min(cap_s[req_i:req_j + 1])):
            return uv
    if t >= T:
        return uv
    if p * 1.0 >= delta * horizon - 1e-9:
        return uv
    return None

# 诊断精修D23：放弃整体V0-V1两次流体差分（把期望需求当确定值→机会成本系统性偏高，Case2长单L5/L6漏收8.95座、两端8.9座搁浅）；改为一次性"单位价值贪心填充"求段级对偶边际价shadow[s]=已实现单位段收益密度（过剩段shadow≈0自动鼓励长单吸收闲置端段），配Erlang-loss随机折减fill=1-exp(-rho)修正确定性偏差，选块按"丢失对偶价+切割碎片惩罚"最小化，终局单调软化
import math
_exp = math.exp

def _up(a, b):
    return (b - a + 1) ** 0.8

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j)) or int(10 * (Lreq ** 0.8))
    frac = (T - t) / T if T > 0 else 0.0

    # 扣除当前请求自身后的剩余期望需求
    rem = {}
    for k, r in remaining_expected.items():
        if k == (req_i, req_j):
            r = r - 1.0
        if r > 1e-9:
            rem[k] = r

    # 段级容量与需求
    cap_s = [0.0] * (M + 2)
    dem_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    # ---- 核心：单位价值贪心填充求段级对偶边际价 shadow[s] ----
    # shadow[s] = 该段每单位座位容量上已实现的平均单位段收益
    # 过剩段（需求<容量）填充不满 → shadow 低 → 长单途经闲置端段几乎零机会成本
    flows = []
    for (a, b), r in rem.items():
        pr = prices.get((a, b)) or int(10 * _up(a, b))
        flows.append((-(pr / (b - a + 1)), a, b, float(r), pr))
    flows.sort()

    blocks = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    segval = [0.0] * (M + 2)
    seguse = [0.0] * (M + 2)
    for _, a, b, r, pr in flows:
        L = b - a + 1
        uv = pr / L
        bl = blocks
        while r > 1e-9 and bl:
            best = None
            for idx, (u, v, c) in enumerate(bl):
                if c <= 1e-9 or u > a or v < b:
                    continue
                gap = (v - u) - L
                edge = 0 if (u == a or v == b) else 1
                key = (gap, edge, -c, idx)
                if best is None or key < best[0]:
                    best = (key, idx)
            if best is None:
                break
            _, idx = best
            u, v, c = bl[idx]
            take = c if c < r else r
            r -= take
            bl[idx] = (u, v, c - take)
            for s in range(a, b + 1):
                segval[s] += uv * take
                seguse[s] += take
            # 分裂子块放回池子（关键：碎片可被后续短流复用）
            if u < a:
                bl.append((u, a - 1, take))
            if b < v:
                bl.append((b + 1, v, take))
            bl = [x for x in bl if x[2] > 1e-9]
        blocks = bl

    shadow = [0.0] * (M + 2)
    for s in range(1, M + 1):
        if seguse[s] > 1e-9:
            shadow[s] = segval[s] / seguse[s]

    # Erlang-loss 随机修正：确定性填充高估实际成交，按段负载 rho 折减
    rho_req = 1.0
    for s in range(req_i, req_j + 1):
        c = cap_s[s]
        d = dem_s[s]
        rho = 3.0 if c <= 1e-9 else d / c
        if rho > 3.0:
            rho = 3.0
        if rho > rho_req:
            rho_req = rho
    fill = 1.0 - _exp(-rho_req)          # 请求段被竞争流占满的概率
    stoch = 0.72 + 0.28 * fill           # 需求未必到来 → 折减机会成本

    # 高价值竞争流到达概率（保护性拒绝仅当强竞争流真的可能来）
    up_req = _up(req_i, req_j)
    lam = 0.0
    for (a, b), r in rem.items():
        if (a, b) != (req_i, req_j) and a <= req_j and b >= req_i:
            pr = prices.get((a, b)) or 10 * _up(a, b)
            if pr >= p - 1e-9:
                lam += r
    comp = 1.0 - _exp(-lam)
    stoch *= (0.62 + 0.38 * comp)

    # 时间因子：早期多持有、后期放松
    horizon = 0.72 + 0.48 * frac

    # ---- 选块：丢失对偶价 + 切割碎片惩罚 最小化 ----
    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        lost = 0.0
        for s in range(u, v + 1):
            lost += shadow[s]
        blk_L = v - u + 1
        # 双切割惩罚：内部切割产生两个碎片
        if u < req_i and req_j < v:
            lost += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac)
        # 端部对齐奖励：避免过早打碎长块
        edge = 1 if (u == req_i or v == req_j) else 0
        key = (lost, -edge, (v - u) - Lreq, u)
        if best is None or key < best[0]:
            best = (key, (u, v), lost)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * stoch * horizon

    if t >= T or p + 1e-9 >= delta:
        return uv
    # 终局激进放松：最后10%时间宁可贱卖不留座
    if frac < 0.08 and p >= 0.45 * delta:
        return uv
    return None

# 交叉融合E021×E016：失分诊断——E021在Case2的L5/L6依然过拒(stk≈8.5)、且无低紧张度快速放行导致早期拒短单；E016的L5 acc仅29.9%(Case2)说明缺乏"长单折减更强"的随机校准、且确定性流体高估机会成本。融合：E016骨架(快速子块放回流体+tight<=0.75快速放行+预排序)，叠加E021的Erlang-loss fill、高价值竞争流comp、按时长加权stoch折减与scale缩放
import math
_exp = math.exp

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, dems):
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_j + req_i - req_i  # placeholder replaced below
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j)) or int(10 * (Lreq ** 0.8))
    frac = (T - t) / T if T > 0 else 0.0

    rem = {}
    for k, r in remaining_expected.items():
        if k == (req_i, req_j):
            r = r - 1.0
        if r > 1e-9:
            rem[k] = r
    dems = []
    for (a, b), r in rem.items():
        dems.append(((b - a + 1) ** 0.8, a, b, float(r)))
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))

    # 段级紧张度（E021基因，取覆盖段最大需求/容量比，更精确）
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r
    tight = 0.0
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            tight = 3.0
            break
        r_ = dem_s[s] / cap_s[s]
        if r_ > tight:
            tight = r_
    if tight > 3.0:
        tight = 3.0
    scale = max(tight, 1e-6) ** 0.45

    # E016基因：低紧张度快速放行（端部贴合优先、最小块）
    if tight <= 0.75:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        return best[1] if best else None

    # E021基因：Erlang-loss fill + 高价值竞争流 comp
    fill = 1.0 - _exp(-tight)
    up_req = Lreq ** 0.8
    lam = 0.0
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)

    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = (0.58 + 0.42 * fill) * (0.52 + 0.48 * comp) * (1.0 - 0.15 * frac) ** lenw

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None
    V0 = _fluid_V(list(blocks0), dems)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc = cc - 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, dems)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:  # 双切割碎片惩罚
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch

    if t >= T:
        return uv
    horizon = 0.65 + 0.35 * frac
    if p >= delta * horizon - 1e-9:
        return uv
    return None

# P2_纯Python次梯度对偶_BPCM: 为每个连续空闲块[u,v]维护影子价格beta, 用缓存+少量次梯度迭代近似Eq.(12)对偶, 按准则 p_ij + beta[u,i-1] + beta[j+1,v] - beta[u,v] > theta 选块接单
import math

_cache = {}

def _state_key(counts, rem_key):
    # 稀疏状态签名（只保留非零块与剩余需求量级）
    items = tuple(sorted(((uv, c) for uv, c in counts.items() if c > 0)))
    return (items, rem_key)

def _expected_total(remaining_expected, M):
    # 聚合每段的未来期望需求 -> 用于对偶初始化与梯度
    seg = [0.0] * (M + 2)
    for (i, j), e in remaining_expected.items():
        if e > 0:
            for s in range(i, j + 1):
                seg[s] += e
    return seg

def _solve_dual(counts, seg_exp, M, n_iter=18):
    """次梯度迭代求 beta[u,v]：约束为未来期望需求可用容量覆盖。
    beta 初始 = 段期望压力; 梯度 = (需求压力 - 可用容量覆盖), 投影到非负。"""
    blocks = [uv for uv, c in counts.items() if c > 0]
    if not blocks:
        return {}
    beta = {}
    # 初始化: 块的影子价格 ~ 平均段压力 * 长度^0.6
    for (u, v) in blocks:
        L = v - u + 1
        avg_p = sum(seg_exp[s] for s in range(u, v + 1)) / L
        beta[(u, v)] = min(12.0, 0.55 * avg_p * (L ** 0.6))
    # 每段可用容量（按块覆盖）
    cap = [0.0] * (M + 2)
    for (u, v) in blocks:
        c = counts[(u, v)]
        for s in range(u, v + 1):
            cap[s] += c
    best = dict(beta)
    best_score = -1e18
    step = 1.2
    for it in range(n_iter):
        # 次梯度: 段 s 的缺口 g[s] = 期望需求 - 可用容量（正=>稀缺=>涨价）
        g = [0.0] * (M + 2)
        for s in range(1, M + 1):
            g[s] = seg_exp[s] - cap[s]
        score = sum(g[s] * g[s] for s in range(1, M + 1))
        if score > best_score:
            best_score = score
            best = dict(beta)
        if score < 1e-9:
            break
        # 更新每个块的价格：块内平均梯度
        for (u, v) in blocks:
            L = v - u + 1
            avg_g = sum(g[s] for s in range(u, v + 1)) / L
            beta[(u, v)] = max(0.0, beta[(u, v)] + step * avg_g / math.sqrt(1.0 + it))
        step *= 0.93
    return best

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    i, j = req_i, req_j
    L = j - i + 1
    p = prices.get((i, j)) or int(10 * L ** 0.8)

    # 候选块
    cands = [(u, v) for (u, v), c in counts.items()
             if c > 0 and u <= i and j <= v]
    if not cands:
        return None

    # 剩余时间与需求规模
    tau = max(1, T - t + 1)
    tot_exp = 0.0
    for (a, b), e in remaining_expected.items():
        if e > 0 and not (b < i or a > j):
            tot_exp += e
    rem_key = int(tot_exp * 2) // 4  # 粗量化以便缓存

    key = (t, _state_key(counts, rem_key))
    beta = _cache.get(key)
    if beta is None:
        seg = _expected_total(remaining_expected, M)
        # 时间折减：期望应按剩余期折算到与当前库存可比尺度
        for s in range(1, M + 1):
            seg[s] = seg[s] * min(1.0, 6.0 / (5.0 + tau * 0.12))
        beta = _solve_dual(counts, seg, M)
        if len(_cache) > 4000:
            _cache.clear()
        _cache[key] = beta

    # 论文准则: p + beta[u,i-1] + beta[j+1,v] - beta[u,v] > theta
    # beta 仅对现存块定义; 子块价值若不在 beta 中, 用相邻块的切比雪夫估计
    def sub(uu, vv):
        if uu > vv:
            return 0.0
        if (uu, vv) in beta:
            return beta[(uu, vv)]
        # 估计: 内含段压力代理
        vals = [beta[(a, b)] for (a, b) in beta if a >= uu and b <= vv]
        return max(vals) if vals else 0.0

    # 动态阈值：末期放宽（机会成本消失）
    frac = tau / float(T)
    theta = 6.0 * max(0.0, min(1.0, frac * 1.6)) * (1.0 + 0.15 * (L - 1))

    best_uv, best_net = None, -1e18
    for (u, v) in cands:
        left = sub(u, i - 1) if i - 1 >= u else 0.0
        right = sub(j + 1, v) if j + 1 <= v else 0.0
        net = p + left + right - beta.get((u, v), 0.0)
        # 平局偏好更贴合的块（减少碎块）
        net -= 0.02 * ((v - u + 1) - L)
        if net > best_net:
            best_net, best_uv = net, (u, v)

    if best_uv is None or best_net <= theta:
        # 末期救险：若几乎无未来需求或最后一两步，接受任何正净值
        if best_net > 0 and (tau <= 3 or tot_exp < 1.0):
            return best_uv
        return None
    return best_uv

# 冠军精细变异E021F：核心流体机会成本保留，改进三点——(1)段级占用概率从纯Erlang fill改为带方差修正的二项/泊松截断混合：fill=1-CDF(cap-1;泊松λ)，长段更准；(2)机会成本δ做轻量单步迭代修正：δ_final=δ·(1+κ·CV)，CV=1/sqrt(λ_total)捕捉低强度需求下确定性流体的系统性低估；(3)Tie-break升级为连续碎片代价项waste^0.75·(1-frac)，替代硬edge偏置，缓解Case1首末段残留5.85与Case2 L5/L6积压
import math
_exp = math.exp

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _pois_ge(lam, k):
    # P[X >= k] 泊松尾，k>=1；lam大时正态近似
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return 1.0 - s

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / T if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None
    V0 = _fluid_V(list(blocks0), rem)

    # ---- 段级统计：λ=需求强度，cap=容量，精确占用概率 fill=P[Pois(λ)>=cap] ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r
    rho = 0.0
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0
            fill = 1.0
            break
        rho = max(rho, lam_s / cap_s[s])
        # 该段被未来需求完全占满的概率（k=ceil(cap)）
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    if rho > 3.0:
        rho = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)  # 数值兜底
    fill = min(max(fill, 0.02), 1.0)
    scale = max(rho, 1e-6) ** 0.45

    # ---- 高价值竞争流 comp + 总需求强度 CV 修正 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    # 方差修正：低强度下确定性流体低估真实占用，CV=1/sqrt(λ)，上限0.5防过激
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)  # 前期不确定大、修正强；后期退化为原δ

    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = (0.58 + 0.42 * fill) * (0.52 + 0.48 * comp) * (1.0 - 0.15 * frac) ** lenw

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 连续碎片代价：对齐边界(零浪费)无惩罚，内嵌切割按浪费量与时间衰减
        Bu = u - req_i
        Bv = req_j - v
        waste = min(Bu, Bv)
        edge_bonus = 0.0
        if waste > 0:
            edge_bonus = (waste ** 0.75) * (1.0 - frac) * 0.55

        key = (delta + edge_bonus, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * (1.0 + kappa * cv)

    horizon = 0.65 + 0.35 * frac
    if t >= T or p >= delta * horizon - 1e-9:
        return uv
    return None

# 诊断精修E029：E021缺陷定位——(a) Case2的L5/L6 stk高达7.4/8.9但acc%仅36.8/14.4，说明"端部大块"被长期囤积，长单到达时又被stoch折减+双切割惩罚联合压低接受率：根源是流体V按长度^0.8排序分配，把端部块留给了几乎不存在的超长确定性需求，实际应按"边际收益密度"竞争分配；(b) Case1的L1/L2 rej+stk说明短单端部碎片未及时收割。升级：1) 流体分配改为"收益密度=price/长度"贪心+按剩余时间衰减的确定性折算 factor=1-exp(-rho_seg)(Erlang占满概率)，修正期望高估; 2) 机会成本 delta 改用二次精化：对接受后的块池做两遍流体(高密先、低密后)估计, 抵消单遍贪心排序偏差; 3) 去掉长单双切割惩罚(它造成长单拒单过狠)，改为按切割产生的碎片价值即时计价; 4) 段级rho用请求区间上的加权平均(而非max, max导致长单rho虚高进而过度拒单)，端部块(u==req_i或v==req_j)给予选择优先。
import math
_exp = math.exp

def _alloc(blocks, a, b, r, dens):
    # 精确子块放回的流体分配；dens为该行程收益密度(price/len)，供块级竞争排序参考
    L = b - a + 1
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append((-(v - u + 1) + L, -c, idx))  # 浪费最小优先，同浪费先大块量
    if not cand:
        return 0.0
    cand.sort()
    total = 0.0
    for _, _, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * dens * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem, cert):
    # cert: 各行程确定性折算系数(基于其覆盖段落的Erlang占满概率)，修正期望高估
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            L = b - a + 1
            dens = 10.0 * (L ** 0.8) / (L * L)  # price/len^2 类边际密度：偏爱高总价短占用
            dems.append((-dens, a, b, r * cert.get((a, b), 1.0)))
    if not dems:
        return 0.0
    dems.sort()
    blocks = list(blocks)
    tot = 0.0
    for nd, a, b, rr in dems:
        if rr <= 1e-9:
            continue
        tot += _alloc(blocks, a, b, rr, 10.0 * ((b - a + 1) ** 0.8) / (b - a + 1))
    return tot

def _cert_factors(rem, counts, M):
    # 每行程的确定性折算：覆盖段的期望占用率(需求/容量)越大，该行程越可能真实兑现
    cap = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap[s] += c
    out = {}
    for (a, b), r in rem.items():
        L = b - a + 1
        # 平均rho：而非max，避免长单被极端段拖高
        rho = 0.0
        for s in range(a, b + 1):
            if cap[s] <= 1e-9:
                rho = 8.0
                break
            rho += r / cap[s]
        else:
            rho /= L
        out[(a, b)] = 1.0 - _exp(-min(rho, 8.0) * 0.55)
    return out

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
