    decay = (1.0 - 0.35 * frac) if Lreq <= 2 else (1.0 - 0.18 * frac)
    stoch = (0.55 + 0.45 * comp) * decay

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        frag = 0.0
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
            frag += 0.4
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
            frag += 0.4
        V1 = _fluid_V(nb, rem, cert)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0
        # 碎片惩罚：切出的边角块价值低（尤其后期），轻量计价替代原重罚
        delta += frag * (1.0 - 0.6 * frac)

        edge = 1 if (u == req_i or v == req_j) else 0
        key = (delta, -edge, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * stoch

    # 末期或价格覆盖机会成本则接受
    horizon = 0.6 + 0.4 * frac
    if t >= T or p >= delta * horizon - 1e-9:
        return uv
    return None

