        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 改进(2)：log型碎片代价 + 贴边对齐奖励（贴端点无缝浪费为0时奖励）
        Bu = u - req_i
        Bv = req_j - v
        waste = min(Bu, Bv)
        edge_bonus = 0.0
        if waste > 0:
            edge_bonus = math.log1p(waste) * (1.0 - frac) * 0.55
        elif Bu == 0 or Bv == 0:
            # 请求恰贴区间一端：完全无碎片，给对齐奖励
            edge_bonus = 0.3 * (1.0 - frac)

        key = (delta + edge_bonus, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * (1.0 + kappa * cv)

    # 改进(3)：容量紧张度自适应horizon——高ρ时更保守保座，低ρ时更宽松出货
    horizon = 0.65 + 0.35 * frac * (1.0 + 0.25 * min(rho, 1.0))
    if t >= T or p >= delta * horizon - 1e-9:
        return uv
    return None

# 交叉融合E032：以E028的"泊松fill占用概率+CV方差修正机会成本"为主干（Case2胜出源），融合E019的"重叠加权tightness"替代纯段级rho（对首末段长块容量按覆盖比例折算，Case1胜出源），碎片代价升级为双梯度edge/waste软惩罚+末段长块保护，缓解Case1首末残留5.6/Case2 L5积压
import math
_exp = math.exp

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return 1.0 - s

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / T if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None
    V0 = _fluid_V(list(blocks0), rem)

    # ---- 混合紧张度：段级泊松fill（E028）+ 重叠加权tightness（E019）----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r
    rho = 0.0
    fill = 0.0
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            rho = 3.0
            fill = 1.0
            break
        lam_s = dem_s[s]
        rho = max(rho, lam_s / cap_s[s])
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    # E019重叠加权tightness：覆盖比例折算的本地容量，对长块边缘请求更准
    cap_here = 0.0
    for (u, v), c in counts.items():
        if c > 0 and u <= req_j and v >= req_i:
            lo = u if u > req_i else req_i
            hi = v if v < req_j else req_j
            cap_here += c * (hi - lo + 1) / (v - u + 1)
    dem_here = 0.0
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i:
            dem_here += r
    tight = dem_here / cap_here if cap_here > 1e-9 else 3.0
    if tight > 3.0:
        tight = 3.0
    # 融合：取段级rho与重叠tightness的加权最大，兼顾两者
    rho_mix = max(rho, 0.55 * rho + 0.45 * tight)
    if rho_mix > 3.0:
        rho_mix = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho_mix)
    fill = min(max(fill, 0.02), 1.0)
    scale = max(rho_mix, 1e-6) ** 0.45

    # ---- 高价值竞争流 comp + CV修正（E028主干）----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = (0.58 + 0.42 * fill) * (0.52 + 0.48 * comp) * (1.0 - 0.15 * frac) ** lenw

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        blk_L = v - u + 1
        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / blk_L) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 双梯度碎片代价：单边切割(贴一边edge)轻罚，双边内嵌按waste^0.75重罚，后期衰减促清仓
        Bu = u - req_i
        Bv = req_j - v
        waste = min(Bu, Bv)
        frag_pen = 0.0
        if waste > 0:
            frag_pen = (waste ** 0.75) * (1.0 - frac) * 0.55
            # 双边内嵌额外惩罚：切割两侧同时浪费，代价更高
            if Bu > 0 and Bv > 0:
                frag_pen *= 1.25
        # 末段长块保护：跨首末段的整块在早期尽量保留给超长L5/L6需求
        if (u == 1 or v == M) and blk_L >= M - 1 and frac > 0.35:
            frag_pen += 0.35 * blk_L ** 0.6 * frac

        key = (delta + frag_pen, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * (1.0 + kappa * cv)

    horizon = 0.65 + 0.35 * frac
    if t >= T or p >= delta * horizon - 1e-9:
        return uv
    return None

# P1_纯Python最小费用流_BPCA_碎片感知：SPFA/贪心增广求腿级对偶势能pi[m]作为机会成本，接受准则 p>=beta*sum(pi)，选座用最小碎片惩罚
def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    L = req_j - req_i + 1
    if L <= 0:
        return None

    # ---------- 1. 腿级剩余容量 ----------
    legcap = [0] * (M + 1)
    for (u, v), c in counts.items():
        if c > 0:
            for m in range(u, v + 1):
                legcap[m] += c
    if any(legcap[m] <= 0 for m in range(req_i, req_j + 1)):
        return None

    # ---------- 2. 候选座位（提前取出，后面还会用到） ----------
    cands = [(u, v, c) for (u, v), c in counts.items()
             if c > 0 and u <= req_i and req_j <= v]
    if not cands:
        return None

    # ---------- 3. 腿级紧张度 ----------
    tight = [0.0] * (M + 1)
    for m in range(1, M + 1):
        dem = 0.0
        for (i, j), e in remaining_expected.items():
            if i <= m <= j and e > 0:
                dem += e
        cap = max(legcap[m], 1e-9)
        tight[m] = dem / cap  # 需求/供给比

    # ---------- 4. 纯Python轻量最小费用流(贪心增广)求对偶势能 pi[m] ----------
    # 把 OD 需求按 单腿价格密度 p/L 降序做最短增广（等价于流体对偶的边际价），
    # 每条腿的 pi[m] = 该腿最后一个被装载 OD 的单腿价格（边际机会成本）。
    pi = [0.0] * (M + 1)
    ods = []
    for (i, j), e in remaining_expected.items():
        if e <= 0:
            continue
        pj = prices.get((i, j))
        if pj is None:
            continue
        ods.append((pj / (j - i + 1), i, j, e))
    ods.sort(reverse=True)
    capleft = [float(x) for x in legcap]
    filled = [False] * (M + 1)
    # 顺序增广：高密度先装，装不下的腿位空着由后续 OD 补
    for dens, i, j, e in ods:
        avail = min(capleft[m] for m in range(i, j + 1))
        if avail <= 0:
            continue
        fl = min(e, avail)
        for m in range(i, j + 1):
            capleft[m] -= fl
            pi[m] = dens  # 边际密度（后续更低的会覆盖 -> 最终为该腿边际价）
        if fl >= e:
            continue
    # 若某腿完全没被未来需求覆盖，用最低密度兜底
    floor_dens = min((p / (j - i + 1) for (i, j), p in prices.items()), default=5.0)
    for m in range(1, M + 1):
        if not filled[m]:
            pi[m] = max(pi[m], 0.0)
        if pi[m] <= 0.0:
            pi[m] = floor_dens * 0.35

    # ---------- 5. 机会成本接受准则（时间衰减 + 供需紧张加压） ----------
    frac = t / float(T)
    opp = 0.0
    for m in range(req_i, req_j + 1):
        tm = tight[m]
        # 紧张度对势能的放大（供需比越大机会成本越高）
        opp += pi[m] * (1.0 + min(tm, 3.0) * 0.22)
    p = prices.get((req_i, req_j), 10 * L)
    # beta 随时间衰减：早期严格，末段清仓
    beta = 1.18 - 0.62 * frac * frac
    # 短途在全面紧张时额外加压（占用大区间机会）
    if L <= 2:
        beta += 0.10 * min(max(tight[req_i], tight[req_j]), 3.0) / 3.0
    # 车尾清仓缓冲
    if T - t <= 4:
        beta *= 0.55
    if p < beta * opp:
        return None

    # ---------- 6. 碎片感知选座（Maximal Sequence 保护） ----------
    best, best_score = None, None
    for u, v, c in cands:
        span = v - u + 1
        slack = span - L
        s = slack * 4.0
        # 贴边好：起贴或终贴减少碎片
        if u != req_i:
            s += 3.0
        if v != req_j:
            s += 3.0
        # 保护全区间 [1,M]（最长极大序列）与长区间
        if (u, v) == (1, M) and L < M:
            s += 14.0 + 3.0 * (M - L)
        elif span >= 4 and slack >= 2:
            s += 2.0
        # 完全贴合最优
        if slack == 0:
            s -= 6.0
        # 优先消耗数量多的块（避免零散块被浪费）
        s -= min(c, 3) * 0.5
        if best_score is None or s < best_score:
            best_score, best = s, (u, v)
    return best

# E033[Diag(E028)]：定向修复E028两大缺陷——(1)"闲量风险折价"：用段级 min(dem/cap)=rho_min 识别供过于求（Case1/2两端段剩5.85/6.75、L5/L6积压源于机会成本高估），把δ乘以 markdown=rho_min^0.55，供过于求时提前放行避免死库存；(2)泊松占用fill已在E028引入但被浪费在纯乘法stoch上，现重构为分段函数：高fill(>0.5)强保护、低fill(<0.2)弱保护，替代错误的连续平滑；(3)末端倾销：frac<0.22时θ随剩余步数线性塌缩到0.35，专治Case2 L6 acc%=15.9与stuck=8.75；(4)选座tie-break保留连续碎片惩罚但改为对齐优先(先零浪费候选)
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        # 关键：把切割后的剩余子块放回池子，供其他行程复用
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # 正确剔除当前请求自身（其到达已含在remaining_expected中）
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量与需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9   # 请求涉及段中最稀缺的供需比
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    V0 = _fluid_V(list(blocks0), rem)

    # ---- 竞争流强度（覆盖本请求且单位价值>=本请求）----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    # 【核心升级1】闲量风险折价：供需比低→未来大概率空驶→机会成本系统性高估
    markdown = max(rho_min, 0.25) ** 0.55
    # 【核心升级2】分段stoch：高fill强保护 / 低fill弱保护（替代原平滑连乘）
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill            # 0.85~1.10
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill            # 0.63~0.85
    else:
        f_fill = 0.42 + 0.30 * fill            # 0.42~0.48（低占用→敢卖）
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    # 【核心升级3】末端倾销：临近结束θ塌缩，清空Case2式L5/L6积压
    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)   # frac=0.22时≈0.65→连续
        theta = max(0.35, theta)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 对齐优先：零浪费候选优先（惩罚浪费的连续碎片代价）
        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# E037[Xover(E034+E026)]：以E034骨架（流体机会成本+闲量markdown+分段fill+末端倾销）为主体，移植E026的"低紧张度快速放行车道"修复其Case2短单过拒（L1 acc%仅50.3、L2 31.1 vs E026的77.7/68.6）：当请求全程段最大供需比<=0.80且fill较低（未来几乎不可能被高价单挤占）时，跳过流体评估直接按"零浪费+端部贴合+最小块"放行；该车道仅在整体松弛时触发，不影响E034的稀缺保护与倾销逻辑
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量与需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    # ==== E026基因：低紧张度快速放行车道（修复Case2短单过拒）====
    # 全程供需松弛(rho<=0.80)且占用概率低(fill<0.35)时，机会成本接近0，
    # 直接端部贴合放行，省去流体评估并避免短单被系统性高估的机会成本拒绝
    if rho <= 0.80 and fill < 0.35:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _fluid_V(list(blocks0), rem)

    # ---- 竞争流强度（覆盖本请求且单位价值>=本请求）----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)
        theta = max(0.35, theta)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# E039[Diag(E034)]：核心修复——(1)彻底抛弃"流体贪心模拟"作为机会成本主体（它把期望当确定值、且浪费双倍 _fluid_V 调用于 O(候选区间) 次，是 224ms 与 L2/L3 拒单率虚高的根源），改为【7 节点段级对偶价格坐标上升】：max Σp_ij·x_ij, s.t. 覆盖约束≤cap_s, x≤λ_ij，迭代得每段影子价 λ_s，机会成本 δ=Σλ_s(请求段)，这是网络流 LP 的对偶，比两次流体模拟更准且 O(30×21×6)≈4k 次操作；(2)随机修正：用泊松尾 fill=Pr[Pois(dem_s)≥cap_s] 对 δ 做 markdown=fill^0.45 折价（低占用→大概率空驶→机会成本折价），替代原先易失控的分段乘子；(3)选座改为"碎片影子价值最小"（Σλ 段价评估切剩的 [u,i-1]/[j+1,v] 碎片），天然零浪费优先，无需 ad-hoc 碎片惩罚；(4)保留末端倾销：frac<0.25 时 θ 线性塌缩到 0.35，修 Case2 长程积压
import math

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # ---- 修正3：剔除当前请求自身 ----
    ods = []
    for (a, b), r in remaining_expected.items():
        if (a, b) == (req_i, req_j):
            r -= 1.0
        if r > 1e-9:
            ods.append((a, b, r, prices.get((a, b), int(10 * ((b - a + 1) ** 0.8)))))
    if not ods:
        return None  # 无未来需求，直接卖

    # ---- 段容量（区间覆盖数之和）与段需求 ----
    cap_s = [0.0] * (M + 1)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 1)
    for a, b, r, _pr in ods:
        for s in range(a, b + 1):
            dem_s[s] += r

    # ---- 核心升级1：段级对偶价格（小网络流 LP 的对偶，坐标上升）----
    lam_s = [0.0] * (M + 1)
    n_it = 26
    for it in range(n_it):
        load = [0.0] * (M + 1)
        for a, b, r, pr in ods:
            s = a
            red = pr
            while s <= b:
                red -= lam_s[s]
                s += 1
            if red > 0.0:  # 值得运载的 OD 全量上载
                s = a
                while s <= b:
                    load[s] += r
                    s += 1
        eta = 0.9 * (0.88 ** it)
        for s in range(1, M + 1):
            if cap_s[s] <= 1e-9:
                lam_s[s] = 1e6
            else:
                lam_s[s] = max(0.0, lam_s[s] + eta * (load[s] - cap_s[s]) / cap_s[s])

    # ---- 请求段机会成本与随机折价（核心升级2）----
    delta = 0.0
    fill = 0.0
    rho_min = 1e9
    for s in range(req_i, req_j + 1):
        delta += lam_s[s]
        c = cap_s[s]
        d = dem_s[s]
        if c <= 1e-9:
            fill = 1.0
        else:
            r = d / c
            if r < rho_min:
                rho_min = r
            # Pr[Pois(d) >= ceil(c)]（正常态每步≤1占用，c 为小数容量取上取整）
            k = int(c - 1e-9) + 1
            if d <= 1e-9:
                f = 0.0
            elif d > 30.0:
                z = (k - 1 - d) / math.sqrt(d)
                f = 0.5 * (1.0 - math.erf(z / 1.4142135623730951)) if -4 < z < 4 else (1.0 if z < 0 else 0.0)
            else:
                term = math.exp(-d); cum = term
                for i in range(1, k):
                    term *= d / i
                    cum += term
                f = max(0.0, 1.0 - cum)
        if f > fill:
            fill = fill if fill >= 1.0 else f
        if fill >= 1.0 and c <= 1e-9:
            break
    if rho_min > 1e9:
        rho_min = 1.0
    fill = min(max(fill, 0.02), 1.0)

    # 供过于求折价：低占用段未来大概率空驶
    markdown = max(rho_min, 0.25) ** 0.5 * (0.45 + 0.55 * fill)

    # ---- 末端倾销（核心升级4）----
    if frac >= 0.25:
        theta = 0.62 + 0.38 * frac
    else:
        theta = max(0.35, 0.35 + 0.62 * (frac / 0.25))

    if t >= T or p >= delta * markdown * theta - 1e-9:
        # ---- 核心升级3：按碎片影子价值最小选座（零浪费优先）----
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            frag = 0.0
            for s in range(u, req_i):
                frag += lam_s[s]
            for s in range(req_j + 1, v + 1):
                frag += lam_s[s]
            waste = (req_i - u) + (v - req_j)
            key = (frag, waste, -(v - u))
            if best is None or key < best[0]:
                best = (key, (u, v))
        return best[1] if best else None
    return None

# E038[Diag(E034)]：用流体对偶影子价μ_s替代O(候选×流体)重模拟——(1)机会成本δ改为覆盖段影子价之和Σμ_s（饱和段=该段被接受的最小价值密度，非饱和段=0），数学上等价LP松弛的对偶解，且把6000次流体重模拟降为每步1次；(2)选座用影子价零损失原则：浪费=块内请求外段的Σμ_s，替代手工frag_cost；(3)修复E034末端倾销在frac<0.22时θ过度塌缩导致的L1/L2漏斗：θ下限提到0.45并按饱和段占比门控（无竞争则直接放行）；(4)泊松占用fill与竞争comp保留分段设计，markdown改用请求段内非饱和占比加权
import math

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = math.exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _shadow_prices(M, rem, counts):
    """流体LP对偶：按单位段价值密度(短行程优先)贪心分配，饱和段影子价=覆盖它的最小接受密度。"""
    cap = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap[s] += c
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            L = b - a + 1
            dems.append((10.0 * (L ** -0.2), a, b, r))  # 每座每段价值
    dems.sort(key=lambda x: (-x[0], x[1] + x[2]))
    mu = [0.0] * (M + 2)      # 影子价（下确界密度，初始INF=未定）
    INF = 1e9
    minacc = [INF] * (M + 2)  # 各段已接受的最小密度
    for dens, a, b, r in dems:
        avail = min(cap[s] for s in range(a, b + 1))
        if avail <= 1e-9:
            continue
        take = avail if avail < r else r
        for s in range(a, b + 1):
            cap[s] -= take
            if take > 1e-9 and dens < minacc[s]:
                minacc[s] = dens
    for s in range(M + 2):
        mu[s] = minacc[s] if minacc[s] < INF else 0.0
    return mu

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    cands = [((u, v), c) for (u, v), c in counts.items() if c > 0 and u <= req_i and req_j <= v]
    if not cands:
        return None

    mu = _shadow_prices(M, rem, counts)

    # 段级供需与占用
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho_min = 1e9
    fill = 0.0
    n_seg = req_j - req_i + 1
    sat_frac = 0.0
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            rho_min = 0.0
            fill = 1.0
            sat_frac += 1.0
            continue
        rho_min = min(rho_min, dem_s[s] / cap_s[s])
        fill = max(fill, _pois_ge(dem_s[s], int(cap_s[s] - 1e-9) + 1))
        if dem_s[s] > cap_s[s]:
            sat_frac += 1.0
    if rho_min > 1e9:
        rho_min = 1.0
    rho_min = min(rho_min, 3.0)
    sat_frac /= n_seg
    fill = min(max(fill, 0.02), 1.0)

    # 竞争流：覆盖本请求、价值密度不低于本请求
    dens_req = Lreq ** -0.2
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** -0.2 >= dens_req - 1e-9:
            lam += r
    comp = 1.0 - math.exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    # 机会成本：影子价之和 × 随机修正
    delta_raw = sum(mu[s] for s in range(req_i, req_j + 1))

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    # 末端θ：无饱和竞争时直接放行（治死库存）；有竞争时塌缩但不低于0.45
    if sat_frac <= 1e-9:
        theta = 0.30 + 0.30 * frac
    elif frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.45 + 0.9091 * frac
    theta = min(max(theta, 0.30), 1.0)

    delta = delta_raw * markdown * stoch * (1.0 + kappa * cv)

    if t >= T or delta <= 1e-9 or p >= delta * theta - 1e-9:
        # 选座：请求外段影子价值浪费最小，tie时短块优先
        best = None
        for (u, v), c in cands:
            waste = 0.0
            for s in range(u, req_i):
                waste += mu[s]
            for s in range(req_j + 1, v + 1):
                waste += mu[s]
            key = (waste, (v - u + 1), u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        return best[1]
    return None

# E042[Xover(E037+E039)]：融合——(1)用E039的"段级对偶价格坐标上升"替代E037的双重流体模拟作为机会成本主体（更快更准，修Case1长单流失）；(2)移植E037的三重随机校准（泊松尾fill、竞争流comp、稀疏cv）对δ做折价，替代E039过强的markdown，修Case2长单过拒（L6 acc%仅20.2、末端剩4.3）；(3)保留E037"低紧张度快速放行车道"（rho低且fill低→零机会成本直接端部贴合放行），(4)选座用E039"碎片影子价值最小+零浪费优先"；(5)末端倾销θ随frac塌缩并按长度加权，鼓励末期长单清仓
import math

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # ---- 剔除当前请求自身 ----
    ods = []
    lam_all = 0.0
    for (a, b), r in remaining_expected.items():
