        if r > 1e-9:
            ods.append((a, b, r, prices.get((a, b), int(10 * ((b - a + 1) ** 0.8)))))
            lam_all += r
    if not ods:
        # 无未来需求：直接按零浪费放行
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            key = ((req_i - u) + (v - req_j), v - u)
            if best is None or key < best[0]:
                best = (key, (u, v))
        return best[1] if best else None

    # ---- 段容量 / 段需求 ----
    cap_s = [0.0] * (M + 1)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 1)
    for a, b, r, _pr in ods:
        for s in range(a, b + 1):
            dem_s[s] += r

    # ---- 段级对偶价格（坐标上升）----
    lam_s = [0.0] * (M + 1)
    n_it = 22
    for it in range(n_it):
        load = [0.0] * (M + 1)
        for a, b, r, pr in ods:
            red = pr
            for s in range(a, b + 1):
                red -= lam_s[s]
            if red > 0.0:
                for s in range(a, b + 1):
                    load[s] += r
        eta = 0.9 * (0.88 ** it)
        for s in range(1, M + 1):
            if cap_s[s] <= 1e-9:
                lam_s[s] = 1e6
            else:
                lam_s[s] = max(0.0, lam_s[s] + eta * (load[s] - cap_s[s]) / cap_s[s])

    # ---- 请求段的紧张度统计 ----
    delta = 0.0
    fill = 0.0
    rho = 0.0
    rho_min = 1e9
    up_req = Lreq ** 0.8
    lam = 0.0
    for s in range(req_i, req_j + 1):
        delta += lam_s[s]
        c = cap_s[s]
        d = dem_s[s]
        if c <= 1e-9:
            fill = 1.0; rho = 3.0; rho_min = 3.0
            break
        r_s = d / c
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        k = int(c - 1e-9) + 1
        if d <= 1e-9:
            f = 0.0
        elif d > 30.0:
            z = (k - 1 - d) / math.sqrt(d)
            f = 0.5 * (1.0 - math.erf(z / 1.4142135623730951)) if -4 < z < 4 else (1.0 if z < 0 else 0.0)
        else:
            term = math.exp(-d); cum = term
            for i in range(1, k):
                term *= d / i
                cum += term
            f = max(0.0, 1.0 - cum)
        fill = max(fill, f)
    # 竞争流强度（覆盖本请求且单位价值不低于本请求）
    for a, b, r, pr in ods:
        if a <= req_j and b >= req_i and pr >= up_req - 1e-9:
            lam += r
    comp = 1.0 - math.exp(-lam)
    rho = min(rho, 3.0)
    if rho_min > 1e9:
        rho_min = 1.0
    fill = min(max(fill, 0.02), 1.0)

    # ==== E037基因：低紧张度快速放行车道 ====
    # 全程松弛(rho<=0.80)且占用概率低(fill<0.35)：机会成本≈0，直接放行
    if rho <= 0.80 and fill < 0.35:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    # ---- 随机校准折价（E037三因子 × E039供过于求折价）----
    markdown = max(rho_min, 0.25) ** 0.5
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)
    delta *= markdown * stoch * (1.0 + kappa * cv)

    # ---- 末端倾销 θ（E037骨架：随时间塌缩，长单加权）----
    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = max(0.35, 0.35 + 0.7182 * (frac / 0.22))

    if t >= T or p >= delta * theta - 1e-9:
        # ---- E039基因：碎片影子价值最小选座（零浪费优先）----
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            frag = 0.0
            for s in range(u, req_i):
                frag += lam_s[s]
            for s in range(req_j + 1, v + 1):
                frag += lam_s[s]
            waste = (req_i - u) + (v - req_j)
            key = (frag, waste, -(v - u))
            if best is None or key < best[0]:
                best = (key, (u, v))
        return best[1] if best else None
    return None

# E045[FineTune(E037)]：冠军精调——①快速放行车道阈值放宽(rho<=0.85, fill<0.40)并加入“长度惩罚门槛”（长单在车道内仍需轻度机会成本校验），修复Case2中长单误放；②接受曲线改为平滑二次式 theta=0.32+0.60*frac+0.25*frac^2，消除原分段折点跳变；③主循环tie-break加入端部贴合奖励(edge贴边-0.06*(1-frac))与碎片成本指数0.8/权重0.60，进一步保护端部可复用容量；④方差修正cv用竞争强度lam直接标定 cv=min(0.5, 1/sqrt(1+lam))，避免lam_all低估竞争
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量与需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    # ==== 快速放行车道（阈值放宽+长度门槛，短单放行更果断、长单保守）====
    lane_ok = (rho <= 0.85 and fill < 0.40) or (rho <= 0.60 and fill < 0.55)
    if lane_ok and Lreq <= 3:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _fluid_V(list(blocks0), rem)

    # ---- 竞争流强度（覆盖本请求且单位价值>=本请求）----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    # 精调④：方差修正直接用竞争流强度标定（竞争越强，机会成本估计越确定）
    cv = min(0.5, 1.0 / math.sqrt(1.0 + lam))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    # 精调②：平滑二次接受曲线，消除分段折点
    theta = 0.32 + 0.60 * frac + 0.25 * frac * frac
    theta = min(max(theta, 0.32), 1.0)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.8) * (1.0 - frac) * 0.60 if waste > 0 else 0.0
        # 精调③：端部贴合奖励（贴边块更易复用，负值降低选中成本）
        edge_bonus = -0.06 * (1.0 - frac) if (u == req_i or v == req_j) else 0.0

        key = (delta + frag_cost + edge_bonus, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# P5_新范式：基于逐腿供需比的影子价格 + 稀缺溢价与碎片化惩罚的净边际收益决策
from math import floor

_ALPHA = 1.05      # 基准接受系数：票价须超过影子成本乘子
_BETA = 0.55       # 时间紧迫度指数：越接近期末越倾向接受
_GAMMA = 0.65      # 长块护留溢价权重（非线性整块价值）

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    L = req_j - req_i + 1
    p = prices.get((req_i, req_j), floor(10 * L ** 0.8))

    # ---- 1) 逐腿影子价格：供需比驱动 ----
    cap = [0] * (M + 1)   # leg l = 区间 l -> l+1, l=1..M-1
    dem = [0.0] * (M + 1)
    for (u, v), c in counts.items():
        if c > 0:
            for l in range(u, v):
                cap[l] += c
    for (a, b), e in remaining_expected.items():
        if e > 0:
            for l in range(a, b):
                dem[l] += e

    shadow = [0.0] * (M + 1)
    for l in range(1, M):
        c = cap[l]
        if c <= 0:
            shadow[l] = 1e6
        else:
            r = dem[l] / c
            # 稀缺溢价：轻度稀缺线性增长，重度稀缺饱和（避免全拒）
            shadow[l] = 10.0 * (0.45 + 1.1 * r if r < 1.0 else 1.55 + 0.25 / (r - 0.2))

    # ---- 2) 接受阈值：影子成本 + 时间衰减 ----
    cost = 0.0
    for l in range(req_i, req_j):
        cost += shadow[l]
    frac = (T - t + 1) / T
    thr = _ALPHA * cost * (frac ** _BETA)
    # 长途票给予轻微折扣（整块非线性价值 > 拆分之和，鼓励长程占用）
    if L >= 4:
        thr *= 0.92
    if p < thr:
        return None

    # ---- 3) 选座：最小化影子价值损耗 + 碎片化惩罚 ----
    # 长块未来需求（按长度）：用于惩罚打碎长连续块
    dem_by_len = [0.0] * (M + 1)
    for (a, b), e in remaining_expected.items():
        dem_by_len[b - a + 1] += e

    best, best_score = None, -1e18
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or req_j > v:
            continue
        bl = v - u + 1
        waste = bl - L
        # 影子损耗：块内被锁定的腿的影子价之和（护住高价值腿的块优先保留）
        lock = 0.0
        for l in range(u, v + 1):
            if l <= M - 1:
                lock += shadow[l]
        # 碎片化惩罚：拆掉长块的未来机会成本（非线性：整块价值更高）
        frag = 0.0
        for k in (L + 1, bl):
            if 2 <= k <= M and dem_by_len[k] > 0:
                frag += dem_by_len[k] * _GAMMA * (k - L) / M
        # 偏好：紧贴贴合（waste小）、低价值锁定、小块被拆
        score = -2.5 * waste - 0.15 * lock - frag
        # 轻微偏好与请求边界对齐（减少端部碎片）
        if u == req_i:
            score += 0.5
        if v == req_j:
            score += 0.5
        if bl == M:  # 整块 [1,M]：除非完全贴合否则重罚
            score -= 0.0 if waste == 0 else (6.0 + 2.0 * waste)
        if score > best_score:
            best_score, best = score, (u, v)
    return best

# E044[DiagRefine(E037)]：用“逐段对偶影子价”替代E037的整池流体模拟——不再把未来需求当确定值做网络流，而是对每个区间段s估计边际价值 dual_s = (需求加权均价/段) * P(Poisson(λ_s) ≥ cap_s)（即E[min(λ,cap)]对容量的真实随机梯度），把机会成本从“整块重排两次流体LP”降为O(M)闭式计算，同时修复E037短单过拒（其对偶价系统性高估：短单Σdual被确定性流体放大）；座位选择按“影子浪费成本+端部贴合+最小块”，末端倾销与低紧张度快车道保留
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # ---- 未来需求（剔除当前请求自身，避免双重计入）----
    rem = {}
    for k, val in remaining_expected.items():
        v = val - 1.0 if k == (req_i, req_j) else val
        if v > 1e-9:
            rem[k] = v

    # ---- 段级容量 / 需求强度 / 加权单段均价 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    lam_s = [0.0] * (M + 2)
    val_s = [0.0] * (M + 2)  # Σ r*p/L（每段期望收益流）
    for (a, b), r in rem.items():
        pr = prices.get((a, b))
        if pr is None:
            pr = 10.0 * ((b - a + 1) ** 0.8)
        pl = pr / (b - a + 1.0)
        for s in range(a, b + 1):
            lam_s[s] += r
            val_s[s] += r * pl

    # ---- 随机对偶影子价：dual_s = 单段均价 * P(需求≥容量) ----
    dual = [0.0] * (M + 2)
    gmax_req = 0.0
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            dual[s] = 1e6
            gmax_req = 1.0
            continue
        lam = lam_s[s]
        if lam <= 1e-9:
            dual[s] = 0.0
        else:
            pp = val_s[s] / lam          # 需求量加权平均单段价
            g = _pois_ge(lam, int(cap_s[s] + 0.5))  # 一张额外座位被占用的概率
            dual[s] = pp * g
            if g > gmax_req:
                gmax_req = g

    delta = 0.0
    for s in range(req_i, req_j + 1):
        delta += dual[s]

    # ---- 竞争强度修正：覆盖本请求且单位价值更高的未来需求 ----
    up = Lreq ** 0.8
    lam_c = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 > up + 1e-9:
            lam_c += r
    comp = 1.0 - _exp(-lam_c)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))

    # ---- 时间折扣 θ（早期严格、末端倾销）+ 竞争/波动上浮 ----
    if frac >= 0.22:
        theta = 0.55 + 0.35 * frac
    else:
        theta = 0.30 + 0.68 * (frac / 0.22)
    kappa = 0.30 * (1.0 - frac)
    thr = delta * theta * (1.0 + comp * 0.35) * (1.0 + kappa * cv)

    accept = (t >= T) or (p >= thr - 1e-9) or (gmax_req <= 0.30 and delta < 0.55 * p)

    # ---- 座位选择：影子浪费成本 + 端部贴合 + 最小块 ----
    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        edge = 0 if (u == req_i or v == req_j) else 1
        waste_cost = 0.0
        if u < req_i:
            for s in range(u, req_i):
                waste_cost += 0.5 * dual[s]   # 侧段仍可服务他人，按半价计损
        if req_j < v:
            for s in range(req_j + 1, v + 1):
                waste_cost += 0.5 * dual[s]
        key = (edge, waste_cost, (v - u) - Lreq, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v))

    if not accept:
        return None
    return best[1] if best is not None else None

# E043[Diagnostic-Refine(E037)]：诊断E037两大缺陷——(A)流体估值把期望需求当"确定到达量"计价，Case2稀疏场景(r≈0.5~1)未来收入被系统性高估，导致L2~L4短中单acc%仅27~32%被过拒；(B)快车道阈值(rho<=0.80)过窄。修正：在_alloc_demand中对每条行程的计价量乘随机到达因子 w=1-exp(-r)（r大→w→1不影响Case1密集场景，r小→按"至少来一单"概率折价，精确修正E[min(D,C)]<min(E[D],C)]偏差）；同时放宽快车道至rho<=0.85/fill<0.42，并保留E034骨架的分裂回池、竞争流、分段fill、末端倾销逻辑
import math
_exp = math.exp

def _pois_ge(lam, k):
