        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr, w):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
