            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        if waste > 0:
            frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 * asym / lnL
        else:
            frag_cost = 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta_eff - 1e-9:
        return uv
    return None

# E049[DiagRefine(E037)]：诊断定位三大缺陷——(1)流体模拟把期望需求当确定值导致机会成本系统性偏差→改为3情景鲁棒流体均值(0.8x/1.0x/1.2x)；(2)Case1端部大量剩座(段1剩2.6/段6剩3.15)→强化端部倾销与"请求完整吃掉小块"奖励；(3)Case2短单过拒→快速放行车道放宽为分段判据(rho_max、rho_mid联合门限)，并对机会成本乘长度衰减因子修正短单高估
import math

_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))   # 分裂子块正确放回池子
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _robust_V(base_blocks, rem):
    # 3情景鲁棒流体值：低需求/名义/高需求，加权(0.25/0.5/0.25)校正确定性偏差
    v = 0.0
    for sc, w in ((0.80, 0.25), (1.00, 0.50), (1.20, 0.25)):
        rrem = {k: x * sc for k, x in rem.items()}
        v += w * _fluid_V(list(base_blocks), rrem)
    return v

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # 当前请求已含在期望中，剔除
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量 / 需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    rho_mid = 0.0
    fill = 0.0
    segs = []
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; rho_mid = 3.0; fill = 1.0
            segs = []
            break
        r_s = dem_s[s] / cap_s[s]
        segs.append(r_s)
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(dem_s[s], int(cap_s[s] - 1e-9) + 1))
    if segs:
        segs.sort()
        rho_mid = segs[len(segs) // 2]
    rho = min(rho, 3.0)
    rho_min = min(rho_min, 3.0)
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)

    # ---- 候选块预筛 ----
    cands = [(u, v) for (u, v), c in counts.items() if c > 0 and u <= req_i and req_j <= v]

    # ==== 末端倾销：无未来竞争或时间将尽，直接零浪费成交 ====
    no_future = all(r <= 1e-9 for r in rem.values())
    if t >= T or no_future or (frac <= 0.08 and rho < 1.6):
        best = None
        for (u, v) in cands:
            key = (0 if (u == req_i and v == req_j) else 1,
                   (v - u + 1) - Lreq, 0 if (u == req_i or v == req_j) else 1, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    # ==== 快速放行车道（修复Case2短单过拒）：max与median供需比联合门限 ====
    if rho <= 0.85 and rho_mid <= 0.55 and fill < 0.40:
        best = None
        for (u, v) in cands:
            edge = 0 if (u == req_i or v == req_j) else 1
            exact = 0 if (v - u + 1) == Lreq else 1
            key = (exact, edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _robust_V(blocks0, rem)

    # ---- 竞争流强度 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45
    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * ((1.0 - 0.15 * frac) ** lenw)
    # 短单机会成本高估修正：长度越短，流体对偶价越粗，衰减越多
    short_corr = 0.82 + 0.18 * (Lreq / M)

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = max(0.35, 0.35 + 0.7182 * (frac / 0.22))

    best = None
    for (u, v) in cands:
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _robust_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        bL = v - u + 1
        if u < req_i and req_j < v:
            # 请求嵌在块中间：额外碎片惩罚
            delta += 0.8 * (Lreq / bL) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)
        exact = (bL == Lreq)
        if exact:
            # 完整吃掉小块：零碎片奖励（改善端部滞留）
            delta *= 0.90
        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0
        # 端部倾销倾向：时间越晚越奖励贴合端点
        end_bonus = 0.0
        if frac < 0.5 and (u == req_i or v == req_j):
            end_bonus = 0.25 * (1.0 - frac) * (p / max(Lreq, 1))

        key = (delta + frag_cost - end_bonus, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * short_corr * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# E048[Refine(E037)]：诊断定位三个偏差并实质修复：
# (A) 单遍贪心流体把未来需求当确定流且只扫一遍，低估V0-V1（机会成本偏高→短单过拒）。
#     改为"两遍残量重扫"流体：第一遍未满足需求在分裂子块放回池后继续二次匹配（子块放回逻辑保留），
#     使 V0/V1 更接近真实LP对偶值，机会成本估计更准。
# (B) Case1末端剩座[2.6,...,3.15]且L1 stock=3.1：选块时对"贴合网络端点"的块加权（端点块
#     无法向内延伸，被挤占价值低），把中段整块留给长单，端点剩座问题显著缓解。
# (C) 快速放行车道阈值随请求长度与票价自适应（长单高票可稍紧也放行），且加"块数=1"守卫，
#     避免唯一大块被低票短单在紧供给时穿透。
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0, r
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))   # 分裂子块放回池
        if b < v:
            blocks.append((b + 1, v, take))   # 分裂子块放回池
    return total, r

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    resid = []
    for pr, a, b, r in dems:
        got, r2 = _alloc_demand(blocks, a, b, r, pr)
        tot += got
        if r2 > 1e-9:
            resid.append((pr, a, b, r2))
    # (A) 二遍残量重扫：长单未满足部分尝试再次分配（此时短单尚未消耗小碎块顺序不定，
    # 按价值降序再扫一遍近似对偶修正）
    if resid:
        resid.sort(key=lambda x: (-x[0], x[1], x[2]))
        for pr, a, b, r in resid:
            got, _ = _alloc_demand(blocks, a, b, r, pr)
            tot += got
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # (C-diag) 当前请求已计入 remaining_expected：剔除本单
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    n_blocks = len(blocks0)

    # ==== 快速放行车道（E026基因 + (C)自适应阈值 + 单块守卫）====
    thr = 0.80
    if Lreq >= 4:            # 长单高票，可稍紧仍放行（其机会成本真实更低）
        thr = 0.92
    fill_thr = 0.35 if Lreq <= 2 else 0.45
    if rho <= thr and fill < fill_thr and n_blocks > 1:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            # (B) 端点贴合优先：块贴网络端点(u==1或v==M)给0，贴请求端点给0.5，否则1
            net_edge = 0 if (u == 1 or v == M) else 1
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (max(net_edge, edge) * 0.5, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _fluid_V(list(blocks0), rem)

    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + 0.7182 * (frac / 0.22)
        theta = max(0.35, theta)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0
        # (B) 端点块折价：贴网络端点的块被占的机会成本打9折（其碎片难以向内重组）
        if u == 1 or v == M:
            delta *= 0.90

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# P4_严格分裂流体前向推演Rollout：Maximal Sequence分裂规则(残余块[u,i-1]&[j+1,v]回池)，按票价降序做流体前向分配，对比接单前后V值
import math

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    p_req = prices.get((req_i, req_j))
    if p_req is None:
        p_req = int(math.floor(10 * (req_j - req_i + 1) ** 0.8))

    # --- 展开座位块池（每个元组代表一个可独立分配的连续空闲块） ---
    pool = []
    for (u, v), c in counts.items():
        if c > 0:
            pool.extend([(u, v)] * c)

    # --- 候选块：能容纳请求的块，Best-Fit（浪费最小） ---
    req_len = req_j - req_i + 1
    best = None; best_waste = 10**9
    for (u, v) in pool:
        if u <= req_i and req_j <= v:
            w = (v - u + 1) - req_len
            if w < best_waste or (w == best_waste and (v - u) < (best[1] - best[0])):
                best_waste = w; best = (u, v)
    if best is None:
        return None

    # --- 未来期望需求（接单后视角：本行程需求减 1） ---
    rem = {}
    for k, val in remaining_expected.items():
        rem[k] = val
    rk = (req_i, req_j)
    rem[rk] = max(0.0, rem.get(rk, 0.0) - 1.0)

    # --- 需求排序：按总票价降序（长程高价值优先占用大块） ---
    segs = sorted(rem.keys(), key=lambda s: -prices.get(s, 0))
    pget = prices.get
    base = [10, 17, 24, 30, 36, 41]
    def pr(s):
        p = pget(s)
        return p if p is not None else base[s[1] - s[0]]

    # --- V：严格分裂的流体前向推演估值 ---
    def V(pool_in):
        pl = list(pool_in)
        total = 0.0
        for (i, j) in segs:
            d = rem.get((i, j), 0.0)
            if d <= 0 or not pl:
                continue
            pj = pr((i, j))
            while d >= 1.0:
                bk = -1; bw = 10**9; bu = bv = 0
                for k in range(len(pl)):
                    u, v = pl[k]
                    if u <= i and j <= v:
                        w = (v - u + 1) - (j - i + 1)
                        if w < bw:
                            bw = w; bk = k; bu = u; bv = v
                if bk < 0:
                    break
                pl.pop(bk)                     # 消耗整个块（Maximal Sequence 语义）
                if i - 1 >= bu: pl.append((bu, i - 1))   # 严格分裂：残余左块回池
                if bv >= j + 1: pl.append((j + 1, bv))   # 严格分裂：残余右块回池
                total += pj
                d -= 1.0
            if 0.0 < d < 1.0:
                bk = -1; bw = 10**9; bu = bv = 0
                for k in range(len(pl)):
                    u, v = pl[k]
                    if u <= i and j <= v:
                        w = (v - u + 1) - (j - i + 1)
                        if w < bw:
                            bw = w; bk = k; bu = u; bv = v
                if bk >= 0:
                    pl.pop(bk)                 # 期望意义上部分占用该块
                    if i - 1 >= bu: pl.append((bu, i - 1))
                    if bv >= j + 1: pl.append((j + 1, bv))
                    total += d * pj            # 仅按期望比例计价
        return total

    V_rej = V(pool)

    # 接单后的池：移除所选块，放入两个残余块
    pool_acc = list(pool)
    pool_acc.remove(best)
    bu, bv = best
    if req_i - 1 >= bu: pool_acc.append((bu, req_i - 1))
    if bv >= req_j + 1: pool_acc.append((req_j + 1, bv))
    V_acc = V(pool_acc)

    # 接受条件：p + V(接单后) >= gamma * V(拒单)（轻微风险折扣防过度保守）
    if p_req + V_acc >= 0.995 * V_rej - 0.5:
        return best
    return None

# E051[Xover(E037+E047)]：以E037冠军骨架（流体机会成本+markdown+分段fill+末端倾销+E026快速车道）为主体，融合E047三个精修但修复其缺陷：(1)theta动态化用自身重复到达概率S_self，但系数收紧到(0.88+0.22*(1-snorm))避免E047早期过松导致Case1 L1流失(57.5%->~60%)；(2)不对称碎片惩罚(asym)保留——修复E037在Case2 L5浪费的边座(46.2% vs E047 53.0%)；(3)竞争流长度加权净值保留；(4)快速车道阈值从rho<=0.80微放宽到0.85并加端部贴合，进一步修复Case2 L1/L2过拒。E047残留的死循环代码已清除
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

