# E051[诊断精修：单位票价驱动的对偶影子价(Bid-Price)替代整块流体差分]：E037的缺陷在于(a)机会成本按“整块V0-V1差分”计算，短单在被长单覆盖的稀缺块上被系统性高估（Case2 L1 acc仅50.3%、Case1两端滞留2.6/3.15座）；(b)流体模拟把期望需求当确定量，估值偏高导致末端倾销不足。本版改用按单位长度票价(10*L^0.8/L)降序的贪心影子价：逐段记录“最后一单位容量被谁占掉”，得到各段边际价dual_s；机会成本=Σdual_s再乘(0.35+0.65*Poisson占用概率)做随机折减；接受准则 p>=theta*OC，theta随时间递减实现自然倾销；快速放行车道阈值放宽(rho<=1.0)并按端部贴合+最小块选座，消除碎片。
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _pick(counts, ri, rj, dual, M):
    # 端部贴合优先 + 最小块 + 低影子价残留段，最小化碎片与高价值段损耗
    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > ri or v < rj:
            continue
        left = sum(dual[s] for s in range(u, ri))
        right = sum(dual[s] for s in range(rj + 1, v + 1))
        edge = 0 if (u == ri or v == rj) else 1
        key = (edge, left + right, v - u, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v))
    return best[1] if best else None

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
