        v = val - 1.0 if k == (req_i, req_j) else val
        if v > 1e-9:
            rem[k] = v

    blocks = [(u, v) for (u, v), c in counts.items() if c > 0 and u <= req_i and req_j <= v]
    if not blocks:
        return None

