    dem = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem[s] += r
    rho = 0.0
    for s in range(req_i, req_j + 1):
        if capr[s] <= 1e-9:
            rho = 1e9
            break
        rho = max(rho, dem[s] / capr[s])
    if rho <= 1.0:
        return _pick(counts, req_i, req_j, [0.0] * (M + 2), M)

    # ---- 影子价：按单位长度票价降序贪心占容量，记录各段边际占用者单价 ----
    dual = [0.0] * (M + 2)
    odfs = []
    for (a, b), r in rem.items():
        L = b - a + 1
        odfs.append((10.0 * (L ** 0.8) / L, a, b, r))
    odfs.sort(reverse=True)
    for up, a, b, r in odfs:
        feas = 1e18
        for s in range(a, b + 1):
            if capr[s] < feas:
                feas = capr[s]
        if feas <= 1e-9:
            continue
        take = r if r < feas else feas
        for s in range(a, b + 1):
            capr[s] -= take
            if capr[s] <= 1e-9:
                # 该段最后容量被单价 up 的需求占掉 -> 边际影子价
                if up > dual[s]:
                    dual[s] = up

    # ---- 机会成本与随机折减（确定性贪心估值偏高，按占用概率折扣）----
    OC = 0.0
    fillp = 1.0
    for s in range(req_i, req_j + 1):
        OC += dual[s]
        fp = _pois_ge(dem[s], int(cap0) + 1) if (cap0 := _cap0(counts, s, req_i, req_j)) > 0 else 1.0
        fillp = min(fillp, max(fp, 0.0))
    if fillp > 1.0:
        fillp = 1.0
    OC *= 0.35 + 0.65 * fillp

    # 时间递减倾销系数
    theta = 0.30 + 0.90 * (frac ** 1.15)

    if p >= theta * OC - 1e-9 or t >= T:
        return _pick(counts, req_i, req_j, dual, M)
    return None

def _cap0(counts, s, req_i, req_j):
    # 段 s 上、且能覆盖当前请求所在区间的可用容量（含当前请求自身资源）
    tot = 0.0
    for (u, v), c in counts.items():
        if c > 0 and u <= s <= v and u <= req_i and req_j <= v:
            tot += c
    return tot

# E051[DiagRefine(E037)]：核心缺陷修复——E037的"流体delta×5个启发式乘子"把机会成本系统性放大（Case2 中期 L2/L4 acc% 仅27~31%）。
# 本次改为对偶竞价(bid-price)主导：先做段级随机性修正——当前请求已从rem中扣除(诊断点3)；每段机会成本 dual_s = 均质价q_s × P(Poisson(lam_s) ≥ cap_s)，
# 即"未来到达真的会抢走该座位"的概率(诊断点1)，天然在松弛时趋于0、紧张时趋于q_s，替代大部分启发式缩放；
# 段间需求相关性用 corr 折减（同一乘客覆盖多段只占一个决策），theta随时间递减+末端倾销保留。
# 精选块仍用端部贴合+最小浪费+碎片惩罚；流体V仅作为短请求的下界校验(诊断点2的子块回放在_alloc_demand中已正确)。
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # 诊断点3：扣除当前请求自身
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
