        for s in range(a, b + 1):
            lam_s[s] += r
            qnum_s[s] += r * pr
    dual_s = [0.0] * (M + 2)
    rho = 0.0
    for s in range(1, M + 1):
        if lam_s[s] > 1e-9 and cap_s[s] > 1e-9:
            sc = _pois_ge(lam_s[s], int(cap_s[s] - 1e-9) + 1)
            q = qnum_s[s] / lam_s[s]
