    up = Lreq ** 0.8
    lam_up = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up - 1e-9:
            lam_up += r
    comp = 1.0 - _exp(-lam_up)

    bid = 0.0
    for s in range(req_i, req_j + 1):
