        return None
    uv = best[1]
    fluid_cost = best[2]
    # 流体作为下界参考：确定性模型高估，按紧张度折扣
    fluid_cost *= (0.35 + 0.30 * min(rho, 2.0)) * (1.0 - 0.20 * frac)

