    # ---- 竞争流强度（覆盖本请求且单位价值>=本请求）----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    # 方差修正：竞争流是Poisson，其标准差为sqrt(lam)，
    # 至少有一个竞争者到达的"上置信"概率为 1-exp(-(lam+sqrt(lam)))，
    # 用它与点估计comp的凸组合(权重0.25)做机会成本的上偏修正
    if lam > 1e-9:
        comp_hi = 1.0 - _exp(-(lam + math.sqrt(lam)))
    else:
        comp_hi = comp
    comp_adj = 0.75 * comp + 0.25 * comp_hi

    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
