        x = frac / 0.25
        theta = 0.35 + 0.3875 * (3.0 * x * x - 2.0 * x * x * x)
        theta = max(0.35, theta)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        # 碎片成本：长度自适应——短单(L1/L2)碎片更致命(剩余小段难以再卖)，
        # 惩罚系数上调至0.62；长单(L>=4)残留段通常仍可覆盖中短需求，降至0.48
        waste = min(u - req_i, req_j - v)
        if waste > 0:
            if Lreq <= 2:
                fw = 0.62
            elif Lreq <= 3:
                fw = 0.55
            else:
                fw = 0.48
            frag_cost = (waste ** 0.75) * (1.0 - frac) * fw
        else:
            frag_cost = 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

