        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    # ==== 快速放行车道（分级）：主车道 rho<=0.85&fill<0.35；次车道 rho<=0.95&fill<0.20 ====
    fast = (rho <= 0.85 and fill < 0.35) or (rho <= 0.95 and fill < 0.20)
    if fast:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    # ==== 长度加权竞争流净值 ====
    lam_self = rem.get((req_i, req_j), 0.0)
    S_self = 1.0 - _exp(-lam_self)

    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            wcover = Lreq / float(b - a + 1)
            lam += r * min(1.0, wcover * 1.25)
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)
        theta = max(0.35, theta)

    # ==== S_self 动态 theta：仅当该行程大概率会再次到达时放宽（且早期不过松）====
    snorm = S_self / (S_self + (1.0 - S_self) * max(Lreq / float(M), 0.35))
    # 修正E052缺陷：snorm>0.5（会回来重买）才放宽至最多1.15，否则保持E037原theta
    if snorm > 0.5:
        theta_eff = theta * (1.0 + 0.30 * (snorm - 0.5))
    else:
        theta_eff = theta * (1.0 - 0.08 * (0.5 - snorm) * 2.0)

    # ==== 不对称碎片惩罚 ====
    rho_right = dem_s[req_j] / cap_s[req_j] if cap_s[req_j] > 1e-9 else 1.0
    rho_left = dem_s[req_i] / cap_s[req_i] if cap_s[req_i] > 1e-9 else 1.0
    asym = 1.0
    if rho_right < rho_left - 0.15:
        asym = 0.85
    elif rho_right > rho_left + 0.15:
        asym = 1.12
    lnL = 1.0 + 0.35 * math.log(Lreq)

    V0 = _fluid_V(list(blocks0), rem)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 * asym / lnL if waste > 0 else 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta_eff - 1e-9:
        return uv
    return None

# E059[DiagnosticRefine(E037)]：诊断显示Case2短/中长单系统性过拒（L1-L4 acc%仅27~50），而Case1表现优秀——核心缺陷是流体机会成本delta对短单存在正向偏差（流体把期望需求当确定值、贪心分配高估被挤占概率）。三处定向修复：①快速放行车道阈值放宽(rho<=0.95且fill<0.45)，中段单也可借道；②对L<=2的短单引入"长度折价因子"压低有效门槛(theta_eff)，直接补偿流体高估；③fill很低(供远大于求)时用比例折扣直接对delta打折，避免长尾期错误拒单。其余骨架(竞争流强度、markdown、末端倾销、碎片惩罚)保持不变
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)   # 剩余部分留在原位
        if u < a:
            blocks.append((u, a - 1, take))  # 分裂左子块放回池
        if b < v:
            blocks.append((b + 1, v, take))  # 分裂右子块放回池
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
