    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
