# P2_纯Python次梯度对偶_BPCM：为每个最大区间维护影子价格 beta[u,v]，容量-需求密度初始化 + 20轮坐标下降做次加性投影，用机会成本准则 p_ij+beta左+beta右-beta全 选块接单
def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    segs = [(u, v) for u in range(1, M + 1) for v in range(u, M + 1)]

    # --- 容量：覆盖 [u,v] 的座位总数 ---
    cap = {}
    for (u, v) in segs:
        c = 0
        for (a, b), n in counts.items():
            if n > 0 and a <= u and v <= b:
                c += n
        cap[(u, v)] = c

    # --- 段内未来期望收入 R[u,v] = sum_{(i,j)⊆[u,v]} p_ij * lambda_ij ---
    R = {}
    for (i, j), lam in remaining_expected.items():
        if not lam:
            continue
        p = prices.get((i, j))
        if p is None:
            continue
        pl = p * lam
        for (u, v) in segs:
            if u <= i and j <= v:
                R[(u, v)] = R.get((u, v), 0.0) + pl

    # --- 对偶变量初始化：收入密度（稀缺时自然升高） ---
    beta = {}
    for s in segs:
        c = cap[s]
        beta[s] = (R.get(s, 0.0) / c) if c > 0 else 1e6

    # --- 坐标下降投影：强制次加性 beta[u,v] <= beta[u,k]+beta[k+1,v] ---
    for _ in range(20):
        changed = False
        for (u, v) in segs:
            if v > u:
                cur = beta[(u, v)]
                best = cur
                for k in range(u, v):
                    cand = beta[(u, k)] + beta[(k + 1, v)]
                    if cand < best:
                        best = cand
                if best < cur - 1e-12:
                    beta[(u, v)] = best
                    changed = True
        if not changed:
            break

    # --- 决策：机会成本准则选块 ---
    p_ij = prices.get((req_i, req_j), 0)
    best_score = -1e18
    best_blk = None
    for (a, b), n in counts.items():
        if n > 0 and a <= req_i and req_j <= b:
            s = p_ij
            if a <= req_i - 1:
                s += beta[(a, req_i - 1)]
            if req_j + 1 <= b:
                s += beta[(req_j + 1, b)]
            s -= beta[(a, b)]
            # 轻微偏好紧凑切块，减少座位碎片化
            s -= (b - a) * 1e-6
            if s > best_score:
                best_score = s
                best_blk = (a, b)

    return best_blk if best_score > 0.0 else None

