    # 期末倾销因子: 越接近终点越宽松, 回收残值
    end_frac = (t - 1) / max(1, T - 1)
    # 基础门槛系数, 短途在紧张时更严, 长途略松
    theta = 0.92 - 0.45 * end_frac
    if L <= 2:
        theta += 0.16 * min(tension, 2.0) * (1.0 - end_frac)
    elif L == 3:
        theta += 0.08 * min(tension, 2.0) * (1.0 - end_frac)

    if p < theta * oc and t < T:
        return None

    # ---------- 4) 碎片感知选座 ----------
    best, best_score = None, None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        waste = (req_i - u) + (v - req_j)  # 切割产生的边角
        score = waste * 10.0
        if u == req_i:
            score -= 3.0  # 贴边优先
        if v == req_j:
            score -= 3.0
        if (u, v) == (1, M):
            score += 6.0  # 保护全程大区间
        score -= c * 0.4  # 同类区间多则用之
        if best_score is None or score < best_score:
            best, best_score = (u, v), score
    return best


