# E061[DiagRefine(E037)]：诊断显示Case2短中长单过拒（L1 50%/L4 27.5%）源于流体机会成本把"期望需求"当确定值，系统性高估挤占概率。三处实质修正：
# (1) 需求随机折减——各OD未来需求按其能被实际接纳的概率缩放（用段级Poisson尾概率的调和估计），机会成本只计算"真正会发生的挤占"；
# (2) 挤占概率加权——最终机会成本乘以 P(竞争需求超过可用容量)（Poisson尾），而非全量计入，短单在松弛环境被大幅放行；
# (3) 分裂块回收已确认正确（_alloc_demand中[a-1]/[b+1]回池），并补上rem中对当前请求先扣减再评估的一致性修正。
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))  # 分裂子块回池
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # 当前请求必已含在期望中，先扣减得到"未来其它需求"
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量 / 需求 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    fill = 0.0
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    # ==== E026基因：低紧张度快速放行车道（保留）====
    if rho <= 0.80 and fill < 0.35:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    # ==== 修正(1)：需求随机折减后的流体 ====
    # 各OD能被接纳的概率近似 = 1 - P(其覆盖段在它到达前已满)，
    # 用段级紧张度 min(cap/dem,1) 的几何均值作为折减系数；
    # 相比确定性流体，把"统计上不会发生"的挤占剔除，显著降低短单机会成本
    rem_r = {}
    for (a, b), r in rem.items():
        ratio = 1.0
        for s in range(a, b + 1):
            if dem_s[s] > 1e-9:
                ratio = min(ratio, min(cap_s[s] / dem_s[s], 1.0))
        # 叠加Poisson占用修正：即便均值足够，仍按尾概率轻度折减
        occ = 1.0
        for s in range(a, b + 1):
            if cap_s[s] > 1e-9:
                occ = min(occ, 1.0 - _pois_ge(dem_s[s], int(cap_s[s] - 1e-9) + 1) * 0.5)
        red = min(1.0, 0.15 + 0.85 * ratio) * (0.6 + 0.4 * occ)
        rr = r * red
        if rr > 1e-9:
            rem_r[(a, b)] = rr

    V0 = _fluid_V(list(blocks0), rem_r)

    # ---- 竞争流强度 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45
    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)
        theta = max(0.35, theta)

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem_r)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        waste = min(u - req_i, req_j - v)
        frag_cost = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0

        key = (delta + frag_cost, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * (1.0 + kappa * cv)

    # ==== 修正(2)：挤占概率加权（Poisson尾）====
    # delta是"若真被挤占"的损失；发生概率为覆盖段上竞争需求超过容量的概率。
    # 短单在中低紧张场景下该尾概率远小于1，直接放行；
    # 高紧张时尾概率→1，退化为E037的稀缺保护。
    cap_cover = min(cap_s[s] for s in range(req_i, req_j + 1)) if all(cap_s[s] > 1e-9 for s in range(req_i, req_j + 1)) else 0
    if cap_cover > 0:
        # 竞争需求的Poisson尾：至少消耗到只剩"零余量"
        pcost = _pois_ge(lam, max(int(cap_cover + 0.5), 1))
        # 末端倾销保护：临近结束尾概率本身失效，强制恢复
        pcost = max(pcost, 0.25 * (1.0 - frac))
        delta *= min(1.0, 0.30 + 0.70 * pcost)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# E063[DiagRefine(E037)]：诊断定位两大缺陷——(1)流体V0-V1把期望需求当确定值且贪心分配的机会成本对中长单(L2/L3)系统性偏高(Case2 acc%仅31/32)；(2)快速放行车道阈值过严(fill<0.35,ρ≤0.8)导致松弛期中长单仍被误拒。升级：改用【对偶影子价bid-price】做接受决策——按单位区间价值降序贪心灌入段级容量，取每段“边际被挤出需求的价值”作为段价π_s，接受条件 p ≥ Σπ_s·随机修正，数学上等价于LP对偶且天然含需求随机性(容量灌满概率即价格)；选座改为最小化π加权的碎片损耗。车道放宽为ρ≤0.95或fill<0.25，并允许短中长单在影子价为零时直接放行
import math

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = math.exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    # 排除当前请求自身
    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks = [(u, v, c) for (u, v), c in counts.items() if c > 0]
    if not blocks:
        return None

    # ---- 段级容量 cap_s ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c

    # ---- 段级需求 ----
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    fill = 0.0
    for s in range(req_i, req_j + 1):
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0
            break
        r_s = dem_s[s] / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(dem_s[s], int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    rho_min = min(rho_min, 3.0)
    if fill < 1e-6:
        fill = 1.0 - math.exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0

    # ---- E026车道（放宽：修复Case2中长单误拒）----
    if rho <= 0.95 or fill < 0.25:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            key = (edge, (v - u) - Lreq, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    # ---- 对偶影子价 π_s：按单位区间价值降序贪心灌段级容量 ----
    # dems: (单位价值, a, b, 期望到达率)
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append((10.0 * ((b - a + 1) ** 0.8) / (b - a + 1), a, b, r))
    pi = [0.0] * (M + 2)
    if dems:
        dems.sort(key=lambda x: (-x[0], x[1], x[2]))
        res = cap_s[:]  # 剩余段级容量
        for upv, a, b, r in dems:
            avail = min(res[s] for s in range(a, b + 1))
            if avail <= 1e-9:
                # 挤出：本需求是段a..b的边际，其单位价值即影子价下界
                for s in range(a, b + 1):
                    if res[s] <= 1e-9 and upv > pi[s]:
                        pi[s] = upv
                continue
            take = avail if avail < r else r
            for s in range(a, b + 1):
                res[s] -= take
            # 部分被挤出时，更新被灌满段的影子价
            if take < r - 1e-9:
                for s in range(a, b + 1):
                    if res[s] <= 1e-9 and upv > pi[s]:
