    scale = max(rho, 1e-6) ** 0.45
    markdown = max(rho_min, 0.25) ** 0.55
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)
        theta = max(0.35, theta)

    oc = oc_raw * scale * stoch * markdown * (1.0 + kappa * cv)

    # ---- 末端倾销 ----
    if frac < 0.08:
        oc *= 0.5

    # ---- 选座：最小化影子价加权的碎片损耗 + 端部贴合 + 小块优先 ----
    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        # 浪费段的影子价损失（确定性切分后不可用部分）
        wcost_l = 0.0
        for s in range(u, req_i):
            wcost_l += pi[s]
        wcost_r = 0.0
        for s in range(req_j + 1, v + 1):
            wcost_r += pi[s]
        wc = min(wcost_l, wcost_r) * 0.6 + max(wcost_l, wcost_r) * 0.25
        waste = min(u - req_i, req_j - v)
        frag = (waste ** 0.75) * (1.0 - frac) * 0.55 if waste > 0 else 0.0
        edge = 0 if (u == req_i or v == req_j) else 1
        key = (edge, wc + frag, (v - u) - Lreq, -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v))
    if best is None:
        return None
    uv = best[1]

    if t >= T or p >= oc * theta - 1e-9:
        return uv
    return None

