            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量与需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    rho = 0.0
    rho_min = 1e9
    inv_harm = 0.0
    fill = 0.0
    seg = req_j - req_i + 1
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; fill = 1.0; inv_harm = float(seg) / 3.0
            break
        r_s = lam_s / cap_s[s]
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        inv_harm += 1.0 / max(r_s, 0.05)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    rho = min(rho, 3.0)
    if rho_min > 3.0:
        rho_min = 3.0
    if fill < 1e-6:
        fill = 1.0 - _exp(-rho)
    fill = min(max(fill, 0.02), 1.0)
    if rho_min > 1e9:
        rho_min = 1.0
    if inv_harm <= 1e-9:
        rho_harm = rho_min
    else:
        rho_harm = seg / inv_harm

    # ==== 快速放行车道（精修①：长度自适应fill阈值 + 端部零碎排除）====
    # 短单(L=1,2)阈值0.42，长单(L=3,4)收紧至~0.33；整段无碎料的块才可走快车道
    fast_fill = 0.42 - 0.045 * (Lreq - 1)
    if rho <= 0.85 and fill < fast_fill and Lreq <= 4:
        best = None
        for (u, v), c in counts.items():
            if c <= 0 or u > req_i or v < req_j:
                continue
            # 端部零碎排除：块端超出请求端超过2段视为产生碎料，不允许快车道
            if (u < req_i - 2) or (v > req_j + 2):
                continue
            edge = 0 if (u == req_i or v == req_j) else 1
            left = 1 if u == req_i else 0
            key = (edge, (v - u) - Lreq, -left, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _fluid_V(list(blocks0), rem)

    # ---- 竞争流强度 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45

    markdown = max(rho_harm, 0.25) ** 0.60
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = 0.35 + (0.7182) * (frac / 0.22)
        theta = max(0.35, theta)

    # 精修②：竞争溢出重估乘子 —— 若段上竞争需求超过段容量的概率高，
    # 该段是稀缺资源，delta应放大；反之（几乎无溢出风险）可适度折扣放行。
    # seg_fill' 用去本单容量(cap-1)后的Poisson溢出概率的均值近似。
    fillp_sum = 0.0
    cnt = 0
    for s in range(req_i, req_j + 1):
        cap = cap_s[s] - 1.0
        if cap <= 1e-9:
            fillp_sum += 1.0
        else:
            fillp_sum += _pois_ge(dem_s[s], int(cap - 1e-9) + 1)
        cnt += 1
    spill = fillp_sum / cnt if cnt else fill
    # 映射到 [0.85, 1.25]：spill=0 -> 0.85（放心卖），spill=0.5 -> ~1.0，spill=1 -> 1.25
    spill_mult = 0.85 + 0.40 * spill

    best = None
    for (u, v), c in counts.items():
        if c <= 0 or u > req_i or v < req_j:
            continue
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _fluid_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)

        wasteL = u - req_i
        wasteR = req_j - v
        if wasteL > 0 or wasteR > 0:
            frag_cost = (wasteL ** 0.7 + wasteR ** 0.7) * (1.0 - frac) * 0.40
        else:
            frag_cost = 0.0

        key = (delta + frag_cost, -(1 if u == req_i else 0), -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta = best[2] * scale * stoch * markdown * spill_mult * (1.0 + kappa * cv)

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# E067[Cross(E061+E048)]：以E061为主干（调和均值markdown+双端0.7次幂碎片代价+左贴合tie-break+末端倾销），融合E048三大优势——①流体值改2情景鲁棒均值(0.85x/1.15x等权)校正确定性偏差但控制耗时；②快速放行车道加rho_mid中位数联合门限且保留A的长单例外(L<=4)；③引入短单机会成本长度衰减short_corr与“完整吃掉小块”0.90奖励，改善端部滞留与短单过拒
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _robust_V(base_blocks, rem):
    # 融合B：情景鲁棒流体（2情景等权，兼顾偏差校正与耗时）
    v = 0.0
    for sc in (0.85, 1.15):
        rrem = {k: x * sc for k, x in rem.items()}
        v += 0.5 * _fluid_V(list(base_blocks), rrem)
    return v

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
