        wasteR = req_j - v
        if wasteL > 0 or wasteR > 0:
            frag_cost = (wasteL ** 0.7 + wasteR ** 0.7) * (1.0 - frac) * 0.40
        else:
            frag_cost = 0.0

        # 修正②：端部贴合释放奖励（压低该块的综合机会成本键）
        b_edge = 0.0
        if touch_left and u == req_i:
            b_edge += 0.25 * (1.0 - 0.5 * frac) * (1.0 - min(rho_harm, 1.5) / 1.5)
        if touch_right and v == req_j:
            b_edge += 0.25 * (1.0 - 0.5 * frac) * (1.0 - min(rho_harm, 1.5) / 1.5)

        key = (delta + frag_cost - b_edge, -(1 if u == req_i else 0), -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    delta_eff = best[2] * scale * stoch * markdown * stoch_bias * (1.0 + kappa * cv)

    # 修正③：末端倾销强化
    if frac < 0.18:
        theta = 0.18
        delta_eff *= (0.35 + frac)
    elif frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = max(0.35, 0.35 + 0.7182 * (frac / 0.22))

    if t >= T or p >= delta_eff * theta - 1e-9:
        return uv
    return None

# E066[DiagRefine(E061)]：针对E061诊断（Case2中长单rej>acc、流体确定值偏差）做四点实质修复：
# ①混合机会成本：fluid_delta(网络流差分) 与 段级对偶价估计器 dual_delta(=Σ_bp_s, bp_s=min(ρ_s,1.25)*段均票价*fill折扣) 按 0.6/0.4 凸组合，单一流体估计在ρ接近1时系统性偏高，对偶价提供下界锚定；
# ②随机凸性修正：确定性流体高估未来收益，对 V 差分乘 corr=1/(1+0.6/sqrt(1+λ_all))，λ大时偏差小、λ小(尾部)时收紧机会成本促成交；
# ③快车道加 ρ_min≤0.75 双门槛且 L≥5 排除（Case2诊断显示 L3-L5 acc%<35% 需保护）；④碎片代价保留双端0.7次幂，tie-break左贴合优先。
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
        if k == (req_i, req_j):
