        L = b - a + 1
        segp = (L ** 0.8)          # 每段单价 = 10*L^0.8/L，系数10全局同乘故省略
        for s in range(a, b + 1):
            dem_s[s] += r
            wsum_s[s] += r * segp / L

    rho = 0.0
    rho_min = 1e9
    inv_harm = 0.0
    fill = 0.0
    seg = Lreq
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
