# P4_严格分裂流体前向推演Rollout：V()按票价密度贪心把未来期望流体需求装入最优匹配空闲块，【严格生成残余块[u,i-1]与[j+1,v]放回池子】，接单当且仅当 p + γ·V(after) ≥ V(before)
def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    GAMMA = 0.90          # 未来收益风险/方差折扣，防过度保守
    EPS = 0.75            # 接受容差（微小机会成本仍可接）

    # ---------- 流体前向推演估值：严格 Maximal Sequence 分裂 ----------
    def V(cnts, rem):
        pool = {}
        for ab, c in cnts.items():
            if c > 0:
                pool[ab] = pool.get(ab, 0) + c
        dems = []
        for ij, q in rem.items():
            if q > 0.02 and ij in prices:
                dems.append((prices[ij] / (ij[1] - ij[0] + 1), ij, q))
        if not dems:
            return 0.0
        dems.sort(reverse=True)
        if len(dems) > 28:            # 限流保性能
            dems = dems[:28]
        total = 0.0
        for _dens, (i, j), q in dems:
            # 最优匹配空闲块：浪费最小优先，容量大者优先
            best_blk = None
            best_key = None
            for (a, b), c in pool.items():
                if c > 0 and a <= i and j <= b:
                    key = ((b - a + 1) - (j - i + 1), -c)
                    if best_key is None or key < best_key:
                        best_key = key
                        best_blk = (a, b)
            if best_blk is None:
                continue
            a, b = best_blk
            c = pool[best_blk]
            take = q if q < c else c          # 流体：允许 fractional
            total += take * prices[(i, j)]
            # ---- 严格分裂：残余块 [a, i-1] 与 [j+1, b] 放回池子继续参与分配 ----
            if take >= c:
                del pool[best_blk]
            else:
                pool[best_blk] = c - take
            if i > a:
                lkey = (a, i - 1)
                pool[lkey] = pool.get(lkey, 0) + take
            if b > j:
                rkey = (j + 1, b)
                pool[rkey] = pool.get(rkey, 0) + take
        return total

    # ---------- 候选空闲块 ----------
    cands = []
    for (a, b), c in counts.items():
        if c > 0 and a <= req_i and req_j <= b:
            cands.append((((b - a + 1) - (req_j - req_i + 1)), (a, b)))
    if not cands:
        return None
    cands.sort()

    key = (req_i, req_j)
    p = prices.get(key, 10 * (req_j - req_i + 1))
    rem_a = dict(remaining_expected)
    if key in rem_a:
        rem_a[key] = max(0.0, rem_a[key] - 1.0)

    V0 = V(counts, rem_a)

    best_blk = None
    best_val = -1e18
    for _w, (a, b) in cands[:6]:      # 最多推演 6 个候选，保性能
        cnts2 = dict(counts)
        c = cnts2.get((a, b), 0)
        if c <= 0:
            continue
        if c - 1 > 0:
            cnts2[(a, b)] = c - 1
        else:
            del cnts2[(a, b)]
        # 本单接下后的严格分裂残余
        if req_i > a:
            lk = (a, req_i - 1)
            cnts2[lk] = cnts2.get(lk, 0) + 1
        if b > req_j:
            rk = (req_j + 1, b)
            cnts2[rk] = cnts2.get(rk, 0) + 1
        val = p + GAMMA * V(cnts2, rem_a)
        if val > best_val:
            best_val = val
            best_blk = (a, b)

    if best_blk is not None and best_val >= V0 - EPS:
        return best_blk
    return None

# E077[Xover(E072+E037)]：以E072主干（2情景鲁棒流体+调和均值markdown+双端0.7幂碎片代价+完整吃块0.90奖励+末端倾销）为主体，针对两亲本共同失分点融合改进：①Case2中长单(L2-L4)接受率过低(27~33%)→在中等紧张区(0.75<rho<1.30)对L2-L4引入midlen_relief=0.88再乘markdown，且把E072的mid_relief范围从(0.8,1.2)扩到(0.75,1.30)并改0.90；②Case1端部L1剩座偏多(段1剩2.1/段6剩3.15)→新增端段倾销通道：当请求恰好覆盖首段或末段且该段rho_mid<=0.5、frac<=0.35时直接端部贴合放行（吸收E037快车道思路但只作用于端部滞留位）；③碎片代价前端系数0.34→0.32进一步鼓励前期吃小块；④短单修正保留缓斜率0.86+0.14*L/M；⑤theta前段斜率0.68→0.62防早期过拒
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _robust_V(base_blocks, rem):
    v = 0.0
    for sc in (0.85, 1.15):
        rrem = {k: x * sc for k, x in rem.items()}
        v += 0.5 * _fluid_V(list(base_blocks), rrem)
    return v

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
