        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

