        else:
            pi[s] = 3.0
    g = max(rho_harm, 0.25) ** 0.5
    for _ in range(2):
        for s in range(1, M + 1):
            pi[s] = max(0.3, min(3.0, pi[s] * g))
    pi_req = sum(pi[s] for s in range(req_i, req_j + 1)) / float(Lreq)

    scale = max(rho, 1e-6) ** 0.45
    markdown = max(rho_harm, 0.25) ** 0.55
