    # ---- 竞争流强度 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45
    markdown = max(rho_harm, 0.25) ** 0.55
    if 0.8 < rho < 1.2:
        markdown *= 0.92
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw
    short_corr = 0.85 + 0.15 * (Lreq / M)

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = max(0.35, 0.35 + 0.70 * (frac / 0.22))

    # E079 thin因子（floor 0.42 防过度放行，与E087保守基调对齐）
    thin = max(0.42, min(1.0, 0.30 + 0.70 * min(rho_after, 1.0)))
    theta *= thin

    # 碎片系数：E087 frac平滑混合
    fcoef = 0.42 + 0.06 * min(1.0, max(0.0, (0.75 - frac) / 0.35))

    best = None
    for (u, v) in cands:
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _robust_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)
        if (v - u + 1) == Lreq:
            delta *= 0.90

        wasteL = u - req_i
        wasteR = req_j - v
        if wasteL > 0 or wasteR > 0:
            frag_cost = (wasteL ** 0.7 + wasteR ** 0.7) * (1.0 - frac) * fcoef
            if frac > 0.4 and wasteL > 0 and wasteR > 0:
                frag_cost *= 1.15
        else:
            frag_cost = -0.02 * (1.0 - frac) if frac < 0.5 else 0.0

        # 主tie-break：左贴合优先
        key = (delta + frag_cost, -(1 if u == req_i else 0), -u, v)
        if best is None or key < best[0]:
            best = (key, (u, v), delta)

    if best is None:
        return None
    uv = best[1]
    # 竞争截断因子（E087的0.18）
    comp_cut = 1.0 + 0.18 * comp * (1.0 - fill)
    delta = best[2] * scale * stoch * markdown * short_corr * (1.0 + kappa * cv) * comp_cut

    if t >= T or p >= delta * theta - 1e-9:
        return uv
    return None

# P1_纯Python最小费用流思想_BPCA_碎片感知：腿级影子价格(对偶势能pi)作为机会成本门槛 + Maximal-Sequence碎片惩罚选座 + 供需紧张时提高短途门槛
def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    L = req_j - req_i + 1
    p = prices.get((req_i, req_j))
    if p is None:
        p = int(10 * (L ** 0.8))

    ivs = [(u, v, c) for (u, v), c in counts.items() if c > 0]
    if not ivs:
        return None

    # ---- 腿级真实空闲座位估计：对每条腿取「覆盖区间 + 其不相交补充区间」的最大组合 ----
    free = [0] * (M + 2)
    for k in range(1, M + 1):
        best = 0
        for (u, v, c) in ivs:
            if u <= k <= v:
                ext = c
                for (a, b, c2) in ivs:
                    if b < u or a > v:
                        if ext + c2 > ext and c2 > 0 and (ext + c2) > best:
                            ext = ext + c2 if ext + c2 > c else ext
                if ext > best:
                    best = ext
        free[k] = best
    if min(free[req_i:req_j + 1]) == 0:
        return None

    # ---- 需求/影子价格：对偶势能 pi[k]（费用流的对偶腿价）----
    dem = [0.0] * (M + 2)      # 腿 k 上的期望剩余需求
    wsum = [0.0] * (M + 2)     # 价格密度加权和
    for (i, j), e in remaining_expected.items():
        if e <= 0:
            continue
        pj = prices.get((i, j))
        if pj is None:
            lj = j - i + 1
            pj = 10 * (lj ** 0.8)
        pd = pj / (j - i + 1)
        for k in range(i, j + 1):
            dem[k] += e
            wsum[k] += e * pd
    pi = [0.0] * (M + 2)
    for k in range(1, M + 1):
        avg_pd = wsum[k] / dem[k] if dem[k] > 1e-9 else 0.0
        press = dem[k] / max(free[k], 0.5)
        # 紧张度放大影子价，宽松时回落（保留超售收益空间）
        pi[k] = avg_pd * (0.45 + 0.55 * min(1.25, press))

    oc = 0.0
    for k in range(req_i, req_j + 1):
        oc += pi[k]

    # ---- 时间与紧张度联合调门槛：越紧张/越早，短途门槛越高 ----
    time_left = (T - t + 1) / float(T)
    beta = 0.62 + 0.50 * (1.0 - time_left)          # 后期更宽松
    if L <= 2:
        beta += 0.10                                 # 短途额外门槛
    if L == M:
        beta = 0.0                                   # 全程票几乎总是接
    if p < beta * oc:
        return None

    # ---- 选座：碎片感知（保长区间 [1,M]，最小化浪费）----
    best_seat, best_score = None, None
    for (u, v, c) in ivs:
        if u <= req_i and req_j <= v and c > 0:
            span = v - u + 1
            waste = span - L
            lpad = req_i - u
            rpad = v - req_j
            # 惩罚破坏最大区间；奖励贴边放置（减少切碎）
            if span == M:
                score = 8.0 + waste * 0.5
            else:
                score = waste * 1.0 + 0.6 * min(lpad, rpad) + 0.25 * abs(lpad - rpad)
            if best_score is None or score < best_score:
                best_score, best_seat = score, (u, v)
    return best_seat

# E100[Refine(E087)]：冠军局部精细变异——保留E087全部骨架（2情景鲁棒流体+调和markdown+快车道+末端倾销+竞争截断+左贴合tie-break），三处精准微创新：①方差修正的需求紧度：引入小样本偏差因子 bias=1-0.35/(1+lam_all)^0.5，使早期低样本阶段rho估计去乐观偏差（降低前期误放长单）；②快车道增加“完美贴合豁免”：Lreq>=5且完美贴合的候选即使fill略超0.42仍放行（保护Case2长单全距占座）；③markdown引入sqrt(n)显著性折扣：当rho_harm与1的差距小于噪声带(1+0.5/sqrt(lam))^{-1}时按比例回拉定价，降低Case1 L2-L3边际误拒
import math
_exp = math.exp

def _pois_ge(lam, k):
    if k <= 0:
        return 1.0
    if lam <= 1e-9:
        return 0.0
    if lam > 25.0:
        z = (k - 1 - lam) / math.sqrt(lam)
        if z > 4.0:
            return 0.0
        if z < -4.0:
            return 1.0
        return 0.5 * (1.0 - math.erf(z / 1.4142135623730951))
    term = _exp(-lam)
    s = term
    for i in range(1, k):
        term *= lam / i
        s += term
    return max(0.0, 1.0 - s)

def _alloc_demand(blocks, a, b, r, pr):
    L = b - a + 1
    total = 0.0
    cand = []
    for idx, (u, v, c) in enumerate(blocks):
        if u <= a and v >= b and c > 1e-9:
            cand.append(((v - u + 1) - L, -c, idx))
    if not cand:
        return 0.0
    cand.sort()
    for waste, ncm, idx in cand:
        if r <= 1e-9:
            break
        u, v, c = blocks[idx]
        take = c if c < r else r
        total += take * pr * L
        r -= take
        blocks[idx] = (u, v, c - take)
        if u < a:
            blocks.append((u, a - 1, take))
        if b < v:
            blocks.append((b + 1, v, take))
    return total

def _fluid_V(blocks, rem):
    dems = []
    for (a, b), r in rem.items():
        if r > 1e-9:
            dems.append(((b - a + 1) ** 0.8, a, b, r))
    if not dems:
        return 0.0
    dems.sort(key=lambda x: (-x[0], x[1], x[2]))
    tot = 0.0
    for pr, a, b, r in dems:
        tot += _alloc_demand(blocks, a, b, r, pr)
    return tot

def _robust_V(base_blocks, rem):
    v = 0.0
    for sc in (0.85, 1.15):
        rrem = {k: x * sc for k, x in rem.items()}
        v += 0.5 * _fluid_V(list(base_blocks), rrem)
    return v

def decide(t, T, M, counts, req_i, req_j, prices, remaining_expected):
    Lreq = req_j - req_i + 1
    p = prices.get((req_i, req_j), int(10 * (Lreq ** 0.8)))
    frac = (T - t) / float(T) if T > 0 else 0.0

    rem = {}
    for k, val in remaining_expected.items():
