            val -= 1.0
        if val > 1e-9:
            rem[k] = val

    blocks0 = [(u, v, float(c)) for (u, v), c in counts.items() if c > 0]
    if not blocks0:
        return None

    # ---- 段级容量与需求强度 ----
    cap_s = [0.0] * (M + 2)
    for (u, v), c in counts.items():
        if c > 0:
            for s in range(u, v + 1):
                cap_s[s] += c
    dem_s = [0.0] * (M + 2)
    for (a, b), r in rem.items():
        for s in range(a, b + 1):
            dem_s[s] += r

    lam_all = 0.0
    for (a, b), r in rem.items():
        lam_all += r

    # 【微创新①】小样本方差修正：早期样本少时rho估计偏乐观，去偏差因子
    bias = 1.0 - 0.35 / (1.0 + lam_all) ** 0.5

    rho = 0.0
    rho_min = 1e9
    rho_mid = 0.0
    inv_harm = 0.0
    fill = 0.0
    seg = req_j - req_i + 1
    segs = []
    for s in range(req_i, req_j + 1):
        lam_s = dem_s[s]
        if cap_s[s] <= 1e-9:
            rho = 3.0; rho_min = 3.0; rho_mid = 3.0; fill = 1.0
            segs = []
            break
        r_s = lam_s / cap_s[s]
        segs.append(r_s)
        rho = max(rho, r_s)
        rho_min = min(rho_min, r_s)
        fill = max(fill, _pois_ge(lam_s, int(cap_s[s] - 1e-9) + 1))
    if segs:
        srt = sorted(segs)
        rho_mid = srt[len(srt) // 2]
        inv_harm = sum(1.0 / max(r, 0.05) for r in srt)
    else:
        inv_harm = float(seg) / 3.0
