    fast_ok = (rho <= 0.88 and rho_mid <= 0.55 and fill < 0.42 and Lreq <= 5)
    if not fast_ok and Lreq >= 5:
        # 完美贴合豁免：长单若存在精确覆盖候选且需求不极端紧张则放行
        for (u, v) in cands:
            if (v - u + 1) == Lreq and rho < 1.05 and fill < 0.55:
                return (u, v)
    if fast_ok:
        best = None
        for (u, v) in cands:
            edge = 0 if (u == req_i or v == req_j) else 1
            exact = 0 if (v - u + 1) == Lreq else 1
            left = 1 if u == req_i else 0
            key = (exact, edge, (v - u) - Lreq, -left, -u, v)
            if best is None or key < best[0]:
                best = (key, (u, v))
        if best is not None:
            return best[1]

    V0 = _robust_V(blocks0, rem)

    # ---- 竞争流强度 ----
    up_req = Lreq ** 0.8
    lam = 0.0
    for (a, b), r in rem.items():
        if a <= req_j and b >= req_i and (b - a + 1) ** 0.8 >= up_req - 1e-9:
            lam += r
    comp = 1.0 - _exp(-lam)
    cv = 0.5 if lam_all <= 4.0 else min(0.5, 1.0 / math.sqrt(lam_all))
    kappa = 0.35 * (1.0 - frac)

    scale = max(rho, 1e-6) ** 0.45
    # 【微创新③】markdown显著性折扣：rho_harm与1的差距若小于噪声带则回拉
    rho_harm_c = max(rho_harm, 0.25)
    noise_band = 0.5 / max(1.0, math.sqrt(max(lam, 1.0)))
    if abs(rho_harm_c - 1.0) < noise_band:
        shrink = abs(rho_harm_c - 1.0) / noise_band
        rho_harm_eff = 1.0 + (rho_harm_c - 1.0) * (0.55 + 0.45 * shrink)
    else:
        rho_harm_eff = rho_harm_c
    markdown = rho_harm_eff ** 0.55
    if 0.8 < rho < 1.2:
        markdown *= 0.92
    if fill > 0.5:
        f_fill = 0.60 + 0.50 * fill
    elif fill > 0.2:
        f_fill = 0.48 + 0.75 * fill
    else:
        f_fill = 0.42 + 0.30 * fill
    f_comp = 0.52 + 0.48 * comp
    lenw = 0.5 + 0.5 * (Lreq / M)
    stoch = f_fill * f_comp * (1.0 - 0.15 * frac) ** lenw
    short_corr = 0.85 + 0.15 * (Lreq / M)

    if frac >= 0.22:
        theta = 0.65 + 0.35 * frac
    else:
        theta = max(0.35, 0.35 + 0.70 * (frac / 0.22))

    fcoef = 0.42 + 0.06 * min(1.0, max(0.0, (0.75 - frac) / 0.35))

    best = None
    for (u, v) in cands:
        nb = []
        for (uu, vv, cc) in blocks0:
            if uu == u and vv == v:
                cc -= 1.0
            if cc > 1e-9:
                nb.append((uu, vv, cc))
        if u < req_i:
            nb.append((u, req_i - 1, 1.0))
        if req_j < v:
            nb.append((req_j + 1, v, 1.0))
        V1 = _robust_V(nb, rem)
        delta = V0 - V1
        if delta < 0.0:
            delta = 0.0

        if u < req_i and req_j < v:
            delta += 0.8 * (Lreq / (v - u + 1)) * (0.3 + 0.7 * frac) * (0.7 + 0.3 * scale)
        if (v - u + 1) == Lreq:
            delta *= 0.90

        wasteL = u - req_i
        wasteR = req_j - v
        if wasteL > 0 or wasteR > 0:
            frag_cost = (wasteL ** 0.7 + wasteR ** 0.7) * (1.0 - frac) * fcoef
            if frac > 0.4 and wasteL > 0 and wasteR > 0:
